(() => {
  'use strict';
  const F=window.DISB_FORMS,E=F.esc,$=id=>document.getElementById(id);
  const STATUS={DRAFT:'Rascunho',PUBLISHED:'Publicado',ARCHIVED:'Arquivado',COMPLETED:'Finalizado',CANCELLED:'Cancelado',PENDING:'Pendente',OPEN:'Em aberto',DONE:'Concluído'};
  const TYPES=F.FORM_TYPES;
  const fmt=v=>v?new Date(v).toLocaleString('pt-BR',{timeZone:'America/Fortaleza'}):'—';
  const day=v=>v?String(v).slice(0,10).split('-').reverse().join('/'):'—';
  const pct=v=>v==null?'Sem avaliação':`${Number(v).toLocaleString('pt-BR',{maximumFractionDigits:2})}%`;
  const tone=v=>v==null?'neutral':v>=90?'good':v>=70?'warn':'bad';
  const badge=(text,kind='neutral')=>`<span class="fm-badge ${kind}">${E(text)}</span>`;
  const empty=(title,detail='')=>`<div class="fm-empty"><span aria-hidden="true">▤</span><strong>${E(title)}</strong>${detail?`<p>${E(detail)}</p>`:''}</div>`;
  let fieldCounter=0;
  const field=(label,html,wide=false)=>{const match=html.match(/^<(?:input|textarea|select)\b[^>]*\s+id="([^"]+)"/),id=match?.[1]||`forms-control-${++fieldCounter}`;if(!match)html=html.replace(/<(input|textarea|select)\b/,`<$1 id="${id}"`);return `<div class="field ${wide?'fm-wide':''}"><label for="${id}">${label}</label>${html}</div>`;};
  const input=(name,value='',attrs='')=>`<input data-fm-meta="${name}" value="${E(value)}" ${attrs}>`;
  const options=(items,value,placeholder='Todos')=>`<option value="">${E(placeholder)}</option>`+items.map(x=>`<option value="${E(x.value??x)}" ${String(x.value??x)===String(value)?'selected':''}>${E(x.label??x)}</option>`).join('');
  const btn=(action,label,attrs='',kind='secondary')=>`<button type="button" class="btn ${kind}" data-fm-action="${action}" ${attrs}>${label}</button>`;
  const head=(label,title,text,actions='')=>`<div class="page-head"><div><div class="breadcrumb">FORMULÁRIOS / ${E(label)}</div><h1>${E(title)}</h1><p>${E(text)}</p></div><div class="actions">${actions}</div></div>`;
  const errorMessage=error=>{
    const m=String(error?.message||error||'Falha na operação.');
    if(/FORM_VERSION_CONFLICT/.test(m))return 'Este registro foi alterado em outra tela. Atualize antes de salvar; suas alterações locais foram preservadas.';
    if(/FORM_REQUIRED:/.test(m))return 'Preencha a pergunta: '+m.split('FORM_REQUIRED:')[1];
    if(/FORM_NOK_NOTE_REQUIRED:/.test(m))return 'Descreva a não conformidade: '+m.split('FORM_NOK_NOTE_REQUIRED:')[1];
    if(/FORM_SCHEDULE_USER_FORBIDDEN/.test(m))return 'Um dos colaboradores não tem acesso ao formulário ou à unidade. Revise as permissões do modelo.';
    if(/FORBIDDEN|42501|UNIDADE_SEM_ACESSO/.test(m))return 'Seu acesso a este formulário ou unidade não está disponível. Atualize as permissões e tente novamente.';
    if(/FORM_EVALUATION_REQUIRED/.test(m))return 'Selecione as pessoas avaliadas antes de preencher.';
    if(/FORM_EVALUATION_LOCKED/.test(m))return 'Essa aplicação já tem pessoas selecionadas. Continue pelo rascunho existente.';
    if(/FORM_PHOTO|FORM_TOO_MANY_PHOTOS/.test(m))return 'Confira as fotos: até 5 por resposta e 40 por aplicação, vinculadas a este registro.';
    if(/42P01|PGRST202|form_definitions.*(not|exist)|Could not find.*(forms_|form_)/i.test(m))return 'O banco precisa da atualização do módulo Formulários (migrações 79 a 81).';
    if(/Failed to fetch|NetworkError|network|fetch/i.test(m))return 'Sem conexão com o servidor. O rascunho permanece salvo neste aparelho.';
    return m;
  };

  function create(adapter){
    const ctx=()=>adapter.context(),can=code=>adapter.hasPermission(code),notify=(s,t='success')=>adapter.toast(s,t);
    let definitions=[],people=[],responses=[],assignments=[],plans=[],builder=null,editingField='',builderTab='data',selectedForm='',response=null,answers={},sectionIndex=0,reportTab='summary',reportPage=0,reportFilter={},busy=false,generation=0,identity='',saveTimer=null,saveChain=Promise.resolve(),dirty=false,clock=null,lastView='',scheduleFormOpen=false,loading=false,activePerson='',pendingStart=null,catalogFilter={},scheduleView='list',calendarMonth='',executionPerson='',uploading=false,myEvaluations=[],myYear=new Date().getFullYear(),myForm='',myEvolution=false;
    const rootFor=view=>$(`view-${view}`);
    const currentKey=()=>`${ctx().user?.id||''}|${ctx().unit||''}`;
    const localKey=r=>`disb_forms_response_v1_${ctx().user?.id}_${r?.id}`;
    const builderKey=()=>`disb_forms_builder_v1_${ctx().user?.id}_${ctx().unit}`;
    const findForm=id=>definitions.find(f=>f.id===id);
    const currentPerson=()=>ctx().profile||{};
    const manage=f=>!!f&&can('FORMS_MANAGE')&&f.units.every(u=>ctx().units.includes(u));
    const fill=f=>!!f&&can('FORMS_FILL')&&f.status==='PUBLISHED'&&(currentPerson().role==='ADMIN'||f.apply_everyone||f.apply_roles?.includes(currentPerson().role)||f.apply_user_ids?.includes(ctx().user.id));
    const report=f=>can('FORMS_REPORT')&&(manage(f)||currentPerson().role==='ADMIN'||f.report_roles?.includes(currentPerson().role)||f.report_user_ids?.includes(ctx().user.id));
    async function rpc(name,args){const {data,error}=await ctx().client.rpc(name,args);if(error)throw error;return data;}
    async function allRows(table,configure){let rows=[];for(let offset=0;;offset+=250){let q=ctx().client.from(table).select('*');q=configure(q).range(offset,offset+249);const {data,error}=await q;if(error)throw error;rows.push(...(data||[]));if(!data||data.length<250)return rows;if(rows.length>=10000)throw Error('O filtro possui mais de 10.000 registros. Reduza o intervalo para consultar e exportar todos os dados.');}}
    function persist(){if(!response)return;try{localStorage.setItem(localKey(response),JSON.stringify({revision:response.revision,answers,at:new Date().toISOString()}));}catch(_e){notify('Não foi possível guardar o rascunho neste aparelho. Salve no servidor antes de sair.','error');}}
    function rememberBuilder(){if(!builder)return;try{localStorage.setItem(builderKey(),JSON.stringify(builder));}catch(_e){}}
    function paintNav(){const nav=$('formsDynamicNav');if(nav)nav.innerHTML='';}
    async function loadDefinitions(){
      const key=currentKey(),token=generation;
      if(!ctx().client||!ctx().user)return;
      if(!navigator.onLine)throw Error('Conecte-se à internet para carregar os formulários da unidade. As respostas já abertas continuam guardadas no aparelho.');
      const {data,error}=await ctx().client.from('form_definitions').select('*').contains('units',[ctx().unit]).order('name');
      if(key!==currentKey()||token!==generation)return;
      if(error)throw error;definitions=data||[];paintNav();
    }
    async function loadPeople(){
      const key=currentKey(),data=await rpc('forms_people_with_areas',{});if(key===currentKey())people=data||[];
    }
    async function start(){
      if(identity!==currentKey()){stop();identity=currentKey();}
      if(!can('FORMS_FILL')&&!can('FORMS_REPORT')&&!can('FORMS_MANAGE')&&!can('FORMS_SELF_VIEW')){stop();return;}
      try{await loadDefinitions();}catch(e){definitions=[];paintNav();console.warn('Formulários',errorMessage(e));}
    }
    function stop(){generation++;clearTimeout(saveTimer);clearInterval(clock);definitions=[];people=[];responses=[];assignments=[];plans=[];builder=null;response=null;answers={};selectedForm='';activePerson='';pendingStart=null;catalogFilter={};scheduleView='list';calendarMonth='';executionPerson='';myEvaluations=[];myYear=new Date().getFullYear();myForm='';myEvolution=false;uploading=false;dirty=false;busy=false;loading=false;identity='';reportFilter={};scheduleFilter={};scheduleFormOpen=false;scheduleResults=[];detailResponse=null;planContext=null;paintNav();for(const v of ['forms-manage','forms-fill','forms-report','forms-schedule','forms-self'])if(rootFor(v))rootFor(v).innerHTML='';}
    function canChangeUnit(){
      if(busy||uploading){notify('Aguarde a conclusão da operação antes de trocar de unidade.','error');return false;}
      if(builder){rememberBuilder();if(!confirm('Trocar de unidade? O rascunho de criação ficará salvo neste aparelho.'))return false;}
      if(response&&response.status==='DRAFT'){persist();if(dirty&&!confirm('Trocar de unidade? Há respostas guardadas neste aparelho que ainda precisam ser sincronizadas.'))return false;}
      return true;
    }
    async function enter(view){
      lastView=view;
      if(identity!==currentKey())await start();
      try{
        if(view==='forms-self'){await loadMyEvaluations();}
        if(view==='forms-manage'){await Promise.all([loadDefinitions(),loadPeople()]);renderManage();}
        if(view==='forms-fill'){if(response)renderResponse();else{await loadDefinitions();await loadOwn();renderCatalog();}}
        if(view==='forms-report'){await loadDefinitions();await loadReport();}
        if(view==='forms-schedule'){await Promise.all([loadDefinitions(),loadPeople()]);await loadSchedule();}
      }catch(e){rootFor(view).innerHTML=head('CONFIGURAÇÃO','Formulários','Modelos e aplicações por unidade.')+`<div class="notice" role="alert">${E(errorMessage(e))}</div>`+btn('refresh','Tentar novamente');}
      paintNav();
    }
    function newBuilder(model=null){
      const section={id:F.id(),title:'Dados',fields:[{id:F.id(),label:'',type:'TEXT',required:true,help:'',scored:false,expected:'YES',allow_na:true,require_note:true}]};
      builder=model?JSON.parse(JSON.stringify(model)):{name:'',description:'',area:'',form_type:'CHECKLIST',units:[ctx().unit],apply_everyone:false,apply_roles:[],apply_user_ids:[],report_roles:['ADMIN'],report_user_ids:[],status:'DRAFT',schema:{evaluation:{enabled:false,area:'',membership:'AREA'},sections:[section]}};
      if(builder.schema.evaluation){delete builder.schema.evaluation.user_ids;builder.schema.evaluation.membership='AREA';}
      builderTab='data';editingField=builder.schema.sections[0]?.fields[0]?.id||'';adapter.openView('forms-manage',true);renderManage();
    }
    function choices(name,items,selected){return `<div class="fm-choice-list">${items.map(item=>`<label><input type="checkbox" data-fm-list="${name}" value="${E(item.value??item)}" ${selected.includes(item.value??item)?'checked':''}><span>${E(item.label??item)}</span></label>`).join('')}</div>`;}
    function renderManage(){
      const box=rootFor('forms-manage');if(!box)return;
      if(!builder){
        let saved=false;try{saved=!!localStorage.getItem(builderKey());}catch(_e){}
        box.innerHTML=head('CRIAÇÃO','Criar formulários','Monte perguntas, organize seções e escolha quem pode preencher e acompanhar.',btn('new','＋ Novo formulário','','primary'))+
          (saved?`<div class="fm-resume notice"><span>Há uma criação guardada neste aparelho.</span>${btn('restore-builder','Retomar criação')}</div>`:'')+
          `<div class="fm-model-grid">${definitions.filter(manage).map(f=>`<article class="card fm-model"><div class="fm-model-top">${badge(STATUS[f.status],f.status==='PUBLISHED'?'good':'neutral')}<small>Versão ${f.version}</small></div><h2>${E(f.name)}</h2><p>${E(f.description||'Sem descrição.')}</p><div class="fm-model-meta">${E(f.area)} · ${E(TYPES[f.form_type]||f.form_type)}<br>${E(f.units.join(' · '))}<br>${F.fields(f.schema).length} perguntas · ${f.schema.sections.length} seções</div><div class="actions">${btn('edit','Editar',`data-id="${E(f.id)}"`)}${btn('preview','Visualizar',`data-id="${E(f.id)}"`)}${btn('duplicate','Duplicar',`data-id="${E(f.id)}"`)}</div></article>`).join('')||empty('Crie o primeiro formulário','Ele ficará na lista de formulários disponíveis para os usuários autorizados.')}</div>`;
        return;
      }
      box.innerHTML=head('CRIAÇÃO',builder.id?'Editar formulário':'Novo formulário','As aplicações iniciadas preservam a versão original das perguntas.',`${btn('close-builder','Voltar')}${btn('save-draft','Salvar rascunho')}${btn('publish',builder.status==='PUBLISHED'?'Salvar e publicar':'Publicar formulário','','primary')}`)+
       `<div class="fm-tabs" role="tablist" aria-label="Etapas de criação">${[['data','1 · Dados e acessos'],['questions','2 · Seções e perguntas'],['preview','3 · Prévia']].map(([id,label])=>`<button type="button" role="tab" aria-selected="${builderTab===id}" class="${builderTab===id?'active':''}" data-fm-action="builder-tab" data-id="${id}">${label}</button>`).join('')}</div>`+
       `<div id="formsBuilderContent">${builderTab==='data'?builderData():builderTab==='questions'?builderQuestions():previewHtml(builder)}</div>`;
    }
    function builderData(){
      const roles=Object.entries(ctx().roles).map(([value,label])=>({value,label})),users=people.map(p=>({value:p.id,label:`${p.name} · ${ctx().roles[p.role]||p.role}`}));
      return `<div class="card"><div class="fm-card-title"><span>01</span><div><h2>Identificação</h2><p>Um nome claro ajuda a equipe a encontrar o formulário.</p></div></div><div class="fm-grid">${field('Nome de exibição *',input('name',builder.name,'maxlength="200" placeholder="Ex.: Inspeção de veículos"'),true)}${field('Descrição',`<textarea data-fm-meta="description" maxlength="350" rows="3" placeholder="Explique o objetivo e quando preencher">${E(builder.description)}</textarea>`,true)}${field('Área responsável *',input('area',builder.area,'maxlength="100" list="formsAreas" placeholder="Ex.: Logística"')+`<datalist id="formsAreas">${[...new Set(['Logística','Armazém','Vendas','Segurança do Trabalho','Administrativo',...definitions.map(f=>f.area)])].map(a=>`<option value="${E(a)}"></option>`).join('')}</datalist>`)}${field('Tipo de formulário *',`<select data-fm-meta="form_type">${!TYPES[builder.form_type]?`<option value="${E(builder.form_type)}" selected>${E(builder.form_type)} · anterior</option>`:''}${Object.entries(TYPES).map(([id,label])=>`<option value="${id}" ${id===builder.form_type?'selected':''}>${label}</option>`).join('')}</select>`)}</div></div>`+
       `<div class="card"><div class="fm-card-title"><span>02</span><div><h2>Unidades e visibilidade</h2><p>O acesso respeita as unidades de cada usuário.</p></div></div>${choices('units',ctx().units,builder.units)}<label class="fm-toggle"><input type="checkbox" data-fm-meta="apply_everyone" ${builder.apply_everyone?'checked':''}><span>Todos os usuários autorizados destas unidades podem preencher</span></label></div>`+
       `<div class="card"><div class="fm-card-title"><span>03</span><div><h2>Permissões</h2><p>Selecione cargos, pessoas específicas ou ambos.</p></div></div><div class="fm-permission-grid"><section><h3>Quem pode preencher</h3>${builder.apply_everyone?'<p class="notice">Todos os usuários das unidades selecionadas, com a permissão de preencher formulários.</p>':choices('apply_roles',roles,builder.apply_roles)+`<details><summary>Pessoas específicas (${builder.apply_user_ids.length})</summary><input class="fm-people-search" type="search" placeholder="Buscar pessoa" aria-label="Buscar pessoas para preencher">${choices('apply_user_ids',users,builder.apply_user_ids)}</details>`}</section><section><h3>Quem pode acompanhar os relatórios</h3>${choices('report_roles',roles,builder.report_roles)}<details><summary>Pessoas específicas (${builder.report_user_ids.length})</summary><input class="fm-people-search" type="search" placeholder="Buscar pessoa" aria-label="Buscar pessoas para acompanhar">${choices('report_user_ids',users,builder.report_user_ids)}</details><p class="fm-help">Cada participante pode consultar as próprias aplicações. Administradores e gestores autorizados do modelo podem acompanhá-lo.</p></section></div></div>`+
       evaluationEditor()+
       (builder.id?`<div class="card fm-archive-row"><div><h3>Disponibilidade</h3><p>Arquivar impede novas aplicações e mantém o histórico.</p></div><select data-fm-meta="status" aria-label="Disponibilidade do formulário">${['DRAFT','PUBLISHED','ARCHIVED'].map(s=>`<option value="${s}" ${builder.status===s?'selected':''}>${STATUS[s]}</option>`).join('')}</select>${btn('save-status','Salvar disponibilidade')}</div>`:'');
    }
    function evaluationEditor(){const config=builder.schema.evaluation||{enabled:false,area:''},members=people.filter(p=>p.units.some(u=>builder.units.includes(u))),areas=[...new Set([...members.map(p=>p.area).filter(Boolean),config.area].filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-BR'));return `<div class="card"><div class="fm-card-title"><span>04</span><div><h2>Avaliação de colaboradores</h2><p>Escolha a área. As pessoas serão selecionadas a cada aplicação.</p></div></div><label class="fm-toggle"><input type="checkbox" data-fm-evaluation="enabled" ${config.enabled?'checked':''}>Avaliar colaboradores de uma área</label>${config.enabled?`<div class="fm-grid">${field('Área avaliada *',`<select data-fm-evaluation="area">${options(areas,config.area,'Selecione a área')}</select>`,true)}</div><p class="fm-help">Ao iniciar o DTO, o sistema mostrará os colaboradores ativos dessa área na unidade escolhida. O aplicador selecionará quem participa daquela avaliação.</p><p class="fm-help">A área de cada pessoa pode ser ajustada em Usuários e perfis. Nas perguntas, escolha se a resposta vale para o grupo ou se cada pessoa terá sua própria resposta.</p>`:''}</div>`;}
    function questionEditor(section,q){
      const open=editingField===q.id,canScore=['BOOLEAN','SINGLE_CHOICE'].includes(q.type),expected=q.type==='BOOLEAN'?[{value:'YES',label:'Sim'},{value:'NO',label:'Não'}]:(q.options||[]);
      return `<article class="fm-question-editor ${open?'open':''}" data-question="${E(q.id)}"><div class="fm-question-heading"><button type="button" data-fm-action="edit-question" data-id="${E(q.id)}"><span class="fm-question-dot">${section.fields.indexOf(q)+1}</span><strong>${E(q.label||'Nova pergunta')}</strong><small>${E(F.TYPES[q.type])}</small></button><div class="fm-icon-actions">${btn('question-up','↑',`data-id="${E(q.id)}" aria-label="Mover pergunta para cima"`)}${btn('question-down','↓',`data-id="${E(q.id)}" aria-label="Mover pergunta para baixo"`)}${btn('question-copy','⧉',`data-id="${E(q.id)}" aria-label="Duplicar pergunta"`)}${btn('question-remove','×',`data-id="${E(q.id)}" aria-label="Remover pergunta"`)}</div></div>${open?`<div class="fm-question-fields fm-grid">${field('Pergunta *',`<textarea rows="2" maxlength="500" data-fm-q="label" data-id="${E(q.id)}" placeholder="O que você precisa verificar?">${E(q.label)}</textarea>`,true)}${builder.schema.evaluation?.enabled?field('Esta resposta vale para',`<select data-fm-q="scope" data-id="${E(q.id)}"><option value="GROUP" ${(q.scope||'GROUP')==='GROUP'?'selected':''}>Todo o grupo avaliado</option><option value="INDIVIDUAL" ${q.scope==='INDIVIDUAL'?'selected':''}>Cada pessoa individualmente</option></select>`):''}${field('Tipo de resposta',`<select data-fm-q="type" data-id="${E(q.id)}">${Object.entries(F.TYPES).map(([v,l])=>`<option value="${v}" ${q.type===v?'selected':''}>${E(l)}</option>`).join('')}</select>`)}${field('Orientação (opcional)',`<input maxlength="500" data-fm-q="help" data-id="${E(q.id)}" value="${E(q.help)}" placeholder="Ajude a pessoa a responder">`)}${q.type.includes('CHOICE')?field('Opções * · uma por linha',`<textarea rows="4" maxlength="4500" data-fm-q="options" data-id="${E(q.id)}">${E((q.options||[]).join('\n'))}</textarea>`,true):''}${q.type==='NUMBER'?field('Valor mínimo',`<input type="number" step="any" data-fm-q="min" data-id="${E(q.id)}" value="${E(q.min??'')}">`)+field('Valor máximo',`<input type="number" step="any" data-fm-q="max" data-id="${E(q.id)}" value="${E(q.max??'')}">`):''}<div class="fm-toggle-grid fm-wide"><label class="fm-toggle"><input type="checkbox" data-fm-q="required" data-id="${E(q.id)}" ${q.required?'checked':''}>Resposta obrigatória</label>${q.type==='BOOLEAN'?`<label class="fm-toggle"><input type="checkbox" data-fm-q="allow_na" data-id="${E(q.id)}" ${q.allow_na?'checked':''}>Permitir “Não se aplica”</label>`:''}${canScore?`<label class="fm-toggle"><input type="checkbox" data-fm-q="scored" data-id="${E(q.id)}" ${q.scored?'checked':''}>Impacta a conformidade</label>`:''}</div>${canScore&&q.scored?field('Resposta conforme',`<select data-fm-q="expected" data-id="${E(q.id)}">${options(expected,q.expected,'Escolha a resposta')}</select>`)+`<label class="fm-toggle"><input type="checkbox" data-fm-q="require_note" data-id="${E(q.id)}" ${q.require_note?'checked':''}>Exigir observação quando não conforme</label>`:''}</div>`:''}</article>`;
    }
    function builderQuestions(){return builder.schema.sections.map((s,i)=>`<section class="card fm-section-editor"><div class="fm-section-heading"><div><small>SEÇÃO ${i+1}</small><input aria-label="Título da seção ${i+1}" data-fm-section="${E(s.id)}" maxlength="150" value="${E(s.title)}"></div><div class="fm-icon-actions">${btn('section-up','↑',`data-id="${E(s.id)}" aria-label="Mover seção para cima"`)}${btn('section-down','↓',`data-id="${E(s.id)}" aria-label="Mover seção para baixo"`)}${btn('section-remove','Remover seção',`data-id="${E(s.id)}"`)}</div></div>${s.fields.map(q=>questionEditor(s,q)).join('')}${btn('add-question','＋ Adicionar pergunta',`data-id="${E(s.id)}"`)}</section>`).join('')+`<div class="fm-builder-bottom">${btn('add-section','＋ Adicionar seção')}<p>Você pode reorganizar as seções e perguntas pelas setas.</p>${btn('builder-tab','Ver prévia','data-id="preview"','primary')}</div>`;}
    function previewHtml(model){return `<div class="notice">Prévia do formulário. Nenhuma aplicação é registrada nesta tela.</div><div class="card"><h2>${E(model.name||'Nome do formulário')}</h2><p>${E(model.description)}</p></div>`+model.schema.sections.map(s=>`<div class="card"><h2>${E(s.title)}</h2>${s.fields.map(f=>`<div class="fm-preview-question"><strong>${E(f.label||'Pergunta sem título')}</strong> ${f.required?badge('Obrigatória'):''} ${f.scored?badge('Impacta conformidade','warn'):''}<small>${E(F.TYPES[f.type])}${f.options?' · '+E(f.options.join(' / ')):''}</small>${f.help?`<p>${E(f.help)}</p>`:''}${f.type==='BOOLEAN'?'<div class="fm-answer-buttons"><span class="yes">Sim</span><span class="no">Não</span><span class="na">N/A</span></div>':'<div class="fm-preview-input">Resposta</div>'}</div>`).join('')}</div>`).join('');}
    async function saveBuilder(status){
      if(busy||!builder)return;rememberBuilder();
      if(!F.clean(builder.name)||!F.clean(builder.area))throw Error('Informe o nome e a área responsável.');
      if(!builder.units.length)throw Error('Selecione ao menos uma unidade.');
      if(!builder.apply_everyone&&!builder.apply_roles.length&&!builder.apply_user_ids.length)throw Error('Selecione quem pode preencher o formulário.');
      F.validateSchema(builder.schema);busy=true;setBusy(true);
      try{const saved=await rpc('save_form_definition',{p_id:builder.id||null,p_expected_version:builder.version||0,p_payload:{...builder,status}});builder=null;localStorage.removeItem(builderKey());await loadDefinitions();renderManage();notify(`${saved.name}: ${STATUS[saved.status].toLowerCase()}.`);}finally{busy=false;setBusy(false);}
    }
    function setBusy(value){document.querySelectorAll('[data-fm-action="publish"],[data-fm-action="save-draft"],[data-fm-action="finish"],[data-fm-action="save-response"]').forEach(b=>b.disabled=value||uploading);}
    async function loadOwn(){const key=currentKey(),rows=await allRows('form_responses',q=>q.eq('unit',ctx().unit).eq('respondent_id',ctx().user.id).neq('status','CANCELLED').order('started_at',{ascending:false}));if(key===currentKey())responses=rows;}
    function responseRows(rows){return `<div class="fm-table-wrap"><table class="fm-table"><thead><tr><th>Registro / formulário</th><th>Aplicador / pessoas avaliadas</th><th>Início e fim</th><th>Duração</th><th>Resultado</th><th>Ações</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${E(r.form_name)}</strong><small>${E(r.code)} · v${r.form_version}</small></td><td>${E(r.respondent_name)}<small>${E((r.evaluated_people||[]).map(p=>p.name).join(' · ')||r.unit)}</small></td><td>${fmt(r.started_at)}<small>${r.completed_at?fmt(r.completed_at):STATUS[r.status]}</small></td><td>${duration(r)}</td><td>${badge(r.status==='COMPLETED'?pct(r.score):STATUS[r.status],r.status==='COMPLETED'?tone(r.score):'warn')}</td><td><div class="actions">${r.status==='DRAFT'&&r.respondent_id===ctx().user.id?btn('resume','Continuar',`data-id="${E(r.id)}"`):btn('detail','Ver respostas',`data-id="${E(r.id)}"`)}${r.status==='COMPLETED'?btn('pdf','PDF',`data-id="${E(r.id)}"`):''}</div></td></tr>`).join('')}</tbody></table></div>`;}
    function renderCatalog(){
      const box=rootFor('forms-fill'),form=null,available=definitions.filter(fill),mine=responses;
      box.innerHTML=head('APLICAR',form?.name||'Preencher formulários',form?.description||'Escolha um formulário ou continue uma aplicação em andamento.',btn('catalog','Todos os formulários')+btn('refresh','Atualizar'))+
       `<div class="fm-unit-banner"><span>Unidade de aplicação</span><strong>${E(ctx().unit)}</strong></div><div class="fm-tabs" role="tablist" aria-label="Aplicações"><button class="active" type="button" data-fm-action="application-tab" data-id="available">Disponíveis (${available.length})</button><button type="button" data-fm-action="application-tab" data-id="drafts">Em andamento (${mine.filter(r=>r.status==='DRAFT').length})</button><button type="button" data-fm-action="application-tab" data-id="completed">Finalizados (${mine.filter(r=>r.status==='COMPLETED').length})</button></div><div id="formsApplicationAvailable"><div class="card fm-catalog-filters">${field('Buscar formulário',`<input id="formsCatalogSearch" type="search" value="${E(catalogFilter.search||'')}" placeholder="Nome do formulário">`)}${field('Tipo de formulário',`<select data-fm-catalog-filter="type">${options(Object.entries(TYPES).map(([value,label])=>({value,label})),catalogFilter.type)}</select>`)}${field('Área',`<select data-fm-catalog-filter="area">${options([...new Set(available.map(f=>f.area))].sort(),catalogFilter.area,'Todas')}</select>`)}</div><div class="fm-model-grid" id="formsAvailableGrid">${available.map(f=>`<article class="card fm-model" data-fm-catalog-key="${E(F.key(f.name+' '+f.area))}" data-fm-catalog-type="${E(f.form_type)}" data-fm-catalog-area="${E(f.area)}"><div class="fm-model-top">${badge(f.area)}${badge(TYPES[f.form_type]||f.form_type)}<small>${F.fields(f.schema).length} perguntas</small></div><h2>${E(f.name)}</h2><p>${E(f.description||TYPES[f.form_type])}</p><small>Versão ${f.version} · ${f.schema.sections.length} seções</small>${btn('start','▶ Iniciar formulário',`data-id="${E(f.id)}"`,'primary')}</article>`).join('')||empty('Nenhum formulário disponível','Verifique a unidade atual e as permissões do modelo.')}</div></div><div id="formsApplicationDrafts" class="hidden">${mine.some(r=>r.status==='DRAFT')?responseRows(mine.filter(r=>r.status==='DRAFT')):empty('Nenhuma aplicação em andamento')}</div><div id="formsApplicationCompleted" class="hidden">${mine.some(r=>r.status==='COMPLETED')?responseRows(mine.filter(r=>r.status==='COMPLETED')):empty('Nenhum formulário finalizado')}</div>`;filterCatalog();
    }
    function filterCatalog(){for(const card of document.querySelectorAll('[data-fm-catalog-key]'))card.classList.toggle('hidden',!!(!card.dataset.fmCatalogKey.includes(F.key(catalogFilter.search||''))||(catalogFilter.type&&card.dataset.fmCatalogType!==catalogFilter.type)||(catalogFilter.area&&card.dataset.fmCatalogArea!==catalogFilter.area)));}
    function duration(r){const seconds=Math.max(0,Math.floor(((r.completed_at?new Date(r.completed_at):new Date())-new Date(r.started_at))/1000));return `${Math.floor(seconds/3600).toString().padStart(2,'0')}:${Math.floor(seconds%3600/60).toString().padStart(2,'0')}:${(seconds%60).toString().padStart(2,'0')}`;}
    async function begin(formId,assignmentId=null){
      if(busy)return;if(!navigator.onLine)throw Error('Conecte-se para iniciar uma aplicação. Depois de iniciada, as respostas também ficam guardadas neste aparelho.');
      if(findForm(formId)?.schema.evaluation?.enabled){const key=currentKey(),targets=await rpc('forms_evaluation_people',{p_form_id:formId,p_unit:ctx().unit});if(key!==currentKey())return;pendingStart={formId,assignmentId};adapter.modal({title:'Quem será avaliado?',subtitle:findForm(formId).schema.evaluation.area,html:targets.length?'<p>Selecione uma ou mais pessoas. Perguntas comuns serão respondidas uma vez; perguntas individuais terão respostas para cada pessoa.</p>'+choices('start_people',targets.map(p=>({value:p.id,label:p.name+' · '+(ctx().roles[p.role]||p.role)})),[]):empty('Nenhum colaborador disponível','Confira a área dos colaboradores em Usuários e perfis e as unidades de acesso.'),actions:targets.length?btn('start-evaluated','Iniciar avaliação','','primary'):''});return;}
      const key=currentKey();busy=true;try{const row=await rpc('start_form_response',{p_form_id:formId,p_unit:ctx().unit,p_id:F.id(),p_assignment_id:assignmentId});if(key!==currentKey())return;await openResponse(row);}finally{busy=false;}
    }
    async function openResponse(row){
      response=row;activePerson=row.evaluated_people?.[0]?.id||'';selectedForm=row.form_id;answers=JSON.parse(JSON.stringify(row.answers||{}));sectionIndex=0;dirty=false;
      try{const saved=JSON.parse(localStorage.getItem(localKey(row))||'null');if(row.status==='DRAFT'&&saved?.revision===row.revision){answers=saved.answers;dirty=JSON.stringify(answers)!==JSON.stringify(row.answers);}else if(saved&&row.status==='DRAFT')notify('Há uma cópia local de outra revisão. Foram carregadas as respostas atuais do servidor.','error');}catch(_e){}
      adapter.openView('forms-fill',true);if(row.status==='COMPLETED'){showDetail(row);response=null;return;}renderResponse();clearInterval(clock);clock=setInterval(()=>{if($('formsElapsed')&&response)$('formsElapsed').textContent=duration(response);},1000);
    }
    function answerBag(id,person=activePerson){const f=F.fields(response.schema_snapshot).find(f=>f.id===id);if(f?.scope==='INDIVIDUAL'&&response.evaluated_people?.length){answers.__evaluations??={};answers.__evaluations[person]??={};return answers.__evaluations[person];}return answers;}
    function currentAnswers(){return activePerson?F.evaluationAnswers(response.schema_snapshot,answers,activePerson):answers;}

    function photoLinks(answer){return (answer?.photos||[]).length?`<div class="fm-photo-grid">${answer.photos.map((path,i)=>`<a data-fm-photo="${E(path)}" target="_blank" rel="noopener"><img alt="Foto ${i+1}" loading="lazy"><span>Abrir foto ${i+1}</span></a>`).join('')}</div>`:'';}
    function photoEditor(field,answer){return `<div class="fm-photo-editor"><div class="actions">${btn('photo-camera','📷 Tirar foto',`data-id="${E(field.id)}"`)}${btn('photo-gallery','Anexar fotos',`data-id="${E(field.id)}"`)}<small>${(answer.photos||[]).length}/5 fotos</small></div><input class="hidden" type="file" accept="image/*" capture="environment" data-fm-photo-input="${E(field.id)}" data-source="camera"><input class="hidden" type="file" accept="image/*" multiple data-fm-photo-input="${E(field.id)}" data-source="gallery"><div class="fm-photo-grid">${(answer.photos||[]).map((path,i)=>`<div><a data-fm-photo="${E(path)}" target="_blank" rel="noopener"><img alt="Foto ${i+1}"><span>Abrir foto ${i+1}</span></a>${btn('photo-remove','Remover do registro',`data-id="${E(field.id)}" data-path="${E(path)}"`)}</div>`).join('')}</div><p class="fm-help">Fotos privadas vinculadas ao registro. É preciso conexão para anexar. Até 40 fotos por aplicação.</p></div>`;}
    async function photoOperation(promise){let timer;try{return await Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('O envio ou carregamento da foto demorou demais. Verifique a conexão e tente novamente.')),30000);})]);}finally{clearTimeout(timer);}}
    async function refreshPhotoLinks(){const links=[...document.querySelectorAll('[data-fm-photo]')],paths=[...new Set(links.map(e=>e.dataset.fmPhoto))];if(!paths.length)return;const key=currentKey(),{data,error}=await photoOperation(ctx().client.storage.from('form-evidence').createSignedUrls(paths,900));if(error){notify('Não foi possível carregar as fotos. Verifique sua conexão.','error');return;}if(key!==currentKey())return;for(const item of data||[])for(const link of links.filter(a=>a.dataset.fmPhoto===item.path&&a.isConnected)){if(item.signedUrl){link.href=item.signedUrl;link.querySelector('img').src=item.signedUrl;}}}
    async function compressPhoto(file){if(!file.type.startsWith('image/'))throw Error('Selecione uma imagem.');if(file.size>25*1024*1024)throw Error('A imagem deve ter até 25 MB antes da redução.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();const scale=Math.min(1,1600/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.85));if(!blob||blob.size>5*1024*1024)throw Error('Não foi possível preparar essa foto. Tente outra imagem.');return blob;}finally{URL.revokeObjectURL(url);}}
    async function addPhotos(id,files,person=activePerson){if(uploading||busy)throw Error('Aguarde a operação atual.');if(!response||response.status!=='DRAFT')return;if(!navigator.onLine)throw Error('Conecte-se para anexar fotos. Suas respostas continuam guardadas neste aparelho.');const bag=answerBag(id,person),entry=bag[id]??={},row=response,key=currentKey(),field=F.fields(row.schema_snapshot).find(f=>f.id===id);if((entry.photos||[]).length+files.length>5||F.evidencePaths(answers).length+files.length>40)throw Error('Adicione até 5 fotos por resposta e 40 por aplicação.');uploading=true;setBusy(true);try{for(const file of files){const blob=await compressPhoto(file),path=`${ctx().user.id}/${row.id}/${F.id()}.jpg`,{error}=await photoOperation(ctx().client.storage.from('form-evidence').upload(path,blob,{contentType:'image/jpeg',upsert:false}));if(error)throw error;if(key!==currentKey()||response?.id!==row.id)return;const current=answerBag(id,person)[id]??={};current.photos??=[];current.photos.push(path);if(field.type==='PHOTO')current.value=[...current.photos];answerChanged();}notify('Fotos anexadas.');}finally{uploading=false;setBusy(false);if(key===currentKey()&&response?.id===row.id)renderResponse();}}

    function answerControl(f,a){
      const v=a?.value;if(f.type==='PHOTO')return '<p class="fm-help">Adicione uma ou mais fotos abaixo.</p>';
      if(f.type==='BOOLEAN')return `<div class="fm-answer-buttons" role="radiogroup" aria-label="${E(f.label)}">${[['YES','Sim',f.scored&&f.expected==='NO'?'no':'yes'],['NO','Não',f.scored&&f.expected==='NO'?'yes':'no'],...(f.allow_na?[['NA','N/A','na']]:[])].map(([value,label,kind])=>`<button type="button" role="radio" aria-checked="${v===value}" class="${kind} ${v===value?'selected':''}" data-fm-action="answer" data-id="${E(f.id)}" data-value="${value}">${label}</button>`).join('')}</div>`;
      if(f.type==='SINGLE_CHOICE')return `<select data-fm-answer="${E(f.id)}" aria-label="${E(f.label)}">${options(f.options,v,'Selecione uma opção')}</select>`;
      if(f.type==='MULTIPLE_CHOICE')return `<div class="fm-multiple-options">${f.options.map(option=>`<label><input type="checkbox" data-fm-multiple="${E(f.id)}" value="${E(option)}" ${Array.isArray(v)&&v.includes(option)?'checked':''}>${E(option)}</label>`).join('')}</div>`;
      if(f.type==='LONG_TEXT')return `<textarea rows="4" maxlength="4000" data-fm-answer="${E(f.id)}" aria-label="${E(f.label)}" placeholder="Digite a resposta">${E(v??'')}</textarea>`;
      return `<input type="${f.type==='NUMBER'?'number':f.type==='DATE'?'date':'text'}" ${f.type==='NUMBER'?`step="any" ${f.min!=null?`min="${Number(f.min)}"`:''} ${f.max!=null?`max="${Number(f.max)}"`:''}`:'maxlength="500"'} data-fm-answer="${E(f.id)}" aria-label="${E(f.label)}" value="${E(v??'')}" placeholder="Digite a resposta">`;
    }
    function answerPart(f,person=null){const pid=person?.id||'',a=(person?F.evaluationAnswers(response.schema_snapshot,answers,pid):answers)[f.id]||{},negative=F.outcome(f,a)==='NOK',key=f.id+(pid?'-'+pid:'');return `<div id="fm-answer-${E(key)}" class="fm-person-answer ${negative?'has-nok':''}" data-fm-person="${E(pid)}" role="group" aria-label="${E(person?person.name+' · '+f.label:f.label)}">${person?`<div class="fm-evaluated-person-name"><strong>${E(person.name)}</strong>${!F.empty(a.value)?badge(negative?'NOK':F.outcome(f,a)==='NA'?'N/A':f.scored?'OK':'Respondido',negative?'bad':F.outcome(f,a)==='NA'?'warn':'good'):badge('Pendente')}</div>`:''}${answerControl(f,a)}${f.type==='PHOTO'||negative||(a.photos||[]).length?photoEditor(f,a):''}<div class="fm-answer-tools"><button type="button" data-fm-action="toggle-note" data-id="${E(f.id)}">▤ Observação${negative&&f.require_note?' *':''}</button><button type="button" data-fm-action="toggle-plan" data-id="${E(f.id)}" ${negative?'':'class="hidden"'}>＋ Plano de ação</button></div><div data-fm-note-box="${E(f.id)}" class="${negative||a.observation?'':'hidden'}"><label class="fm-help" for="fm-note-${E(key)}">${negative?'Descreva o problema':'Observação'}</label><textarea id="fm-note-${E(key)}" rows="3" maxlength="2000" data-fm-note="${E(f.id)}" placeholder="Descreva o que foi observado">${E(a.observation||'')}</textarea></div><div data-fm-plan-box="${E(f.id)}" class="${negative&&a.plan?'':'hidden'}"><label class="fm-help" for="fm-plan-${E(key)}">Plano de ação inicial · opcional</label><textarea id="fm-plan-${E(key)}" rows="3" maxlength="2000" data-fm-plan="${E(f.id)}" placeholder="O que será feito para corrigir?">${E(a.plan||'')}</textarea></div></div>`;}
    function renderResponse(){
      if(!response)return;const schema=response.schema_snapshot,section=schema.sections[sectionIndex],score=F.score(schema,answers),progress=requiredProgress(),people=response.evaluated_people||[],allAnswers=people.length?people.map(p=>F.evaluationAnswers(schema,answers,p.id)):[answers];
      rootFor('forms-fill').innerHTML=head('APLICAÇÃO',response.form_name,`${response.code} · ${response.unit} · Aplicador: ${response.respondent_name}`,btn('back-catalog','Voltar aos formulários'))+
       `<div class="card fm-application-bar"><div><strong id="formsProgress">${progress.answered} de ${progress.total} obrigatórias respondidas</strong><div class="fm-progress"><i style="width:${progress.total?progress.answered/progress.total*100:100}%"></i></div></div><div class="fm-application-timer"><span>Tempo de aplicação</span><strong id="formsElapsed">${duration(response)}</strong></div><div id="formsLiveScore">${badge(pct(score.percent),tone(score.percent))}</div></div>`+
       (people.length?`<div class="card fm-evaluated-bar"><strong>Área avaliada: ${E(schema.evaluation.area)}</strong><p>Cada pergunta individual tem respostas separadas por pessoa. As perguntas de grupo valem para todos.</p><div class="fm-evaluated-names">${people.map(p=>badge(p.name,'brand')).join('')}</div></div>`:'')+
       `<div class="fm-tabs fm-section-tabs" role="tablist" aria-label="Seções do formulário">${schema.sections.map((s,i)=>`<button type="button" role="tab" aria-selected="${i===sectionIndex}" class="${i===sectionIndex?'active':''}" data-fm-action="section" data-id="${i}">${E(s.title)}<small>${s.fields.filter(f=>allAnswers.every(a=>!F.empty(a[f.id]?.value))).length}/${s.fields.length}</small></button>`).join('')}</div><div id="formsAnswerErrors" class="notice hidden" role="alert"></div><div class="fm-response-questions">${section.fields.map(f=>`<article class="card fm-answer-card"><div class="fm-answer-title"><strong>${E(f.label)}</strong><div>${f.required?badge('Obrigatória','bad'):badge('Opcional')}${f.scored?badge('Impacta conformidade','warn'):''}${people.length?badge(f.scope==='INDIVIDUAL'?'Uma resposta por pessoa':'Todo o grupo','brand'):''}</div></div>${f.help?`<p class="fm-help">${E(f.help)}</p>`:''}${f.scope==='INDIVIDUAL'&&people.length?people.map(p=>answerPart(f,p)).join(''):answerPart(f)}</article>`).join('')}<div class="card"><label class="fm-help" for="formsSectionNote">Observações desta seção · opcional</label><textarea id="formsSectionNote" data-fm-section-note="${E(section.id)}" rows="3" maxlength="2000" placeholder="Informações adicionais sobre esta seção">${E(answers.__sections?.[section.id]||'')}</textarea></div></div><div class="fm-fill-footer"><div><strong id="formsSaveStatus">${dirty?'Alterações guardadas neste aparelho':'Rascunho salvo no servidor'}</strong><small>${navigator.onLine?'As respostas são salvas automaticamente.':'Sem internet. Conecte-se para sincronizar e finalizar.'}</small></div><div class="actions">${btn('discard','Descartar rascunho')}${btn('save-response','Salvar agora')}${sectionIndex?btn('previous-section','← Anterior'):''}${sectionIndex<schema.sections.length-1?btn('next-section','Próxima →','','primary'):btn('finish','Finalizar formulário','','primary')}</div></div>`;
      paintNav();void refreshPhotoLinks().catch(e=>notify(errorMessage(e),'error'));
    }
    function answerChanged(){dirty=true;persist();if($('formsSaveStatus'))$('formsSaveStatus').textContent='Alterações guardadas neste aparelho';clearTimeout(saveTimer);if(navigator.onLine)saveTimer=setTimeout(()=>saveResponse(false).catch(e=>{if($('formsSaveStatus'))$('formsSaveStatus').textContent=errorMessage(e);}),1000);updateProgress();}
    function requiredProgress(){const rows=response.evaluated_people?.length?response.evaluated_people.map(p=>F.evaluationAnswers(response.schema_snapshot,answers,p.id)):[answers],required=F.fields(response.schema_snapshot).filter(f=>f.required);return {total:rows.length*required.length,answered:rows.reduce((n,a)=>n+required.filter(f=>!F.empty(a[f.id]?.value)).length,0)};}
    function updateProgress(){if(!response)return;const s=F.score(response.schema_snapshot,answers),p=requiredProgress();if($('formsProgress'))$('formsProgress').textContent=`${p.answered} de ${p.total} obrigatórias respondidas`;const bar=document.querySelector('.fm-application-bar .fm-progress i');if(bar)bar.style.width=`${p.total?p.answered/p.total*100:100}%`;if($('formsLiveScore'))$('formsLiveScore').innerHTML=badge(pct(s.percent),tone(s.percent));}
    async function saveResponse(finalize){
      clearTimeout(saveTimer);
      const expectedId=response?.id,expectedContext=currentKey();
      const operation=async()=>{
        if(response?.id!==expectedId||currentKey()!==expectedContext)return;
        if(!response||response.status!=='DRAFT')return;
        if(finalize&&uploading)throw Error('Aguarde o envio das fotos antes de finalizar.');
        if(!navigator.onLine){persist();if(finalize)throw Error('Conecte-se à internet para sincronizar as respostas e finalizar.');return;}
        const check=F.validateResponse(response.schema_snapshot,answers,response.evaluated_people,finalize);
        if(check.errors.length){showAnswerErrors(check.errors);throw Error(check.errors[0].message);}
        const row=response,submitted=JSON.parse(JSON.stringify(answers)),key=currentKey();
        setBusy(true);
        try{const saved=await rpc('save_form_response',{p_id:row.id,p_expected_revision:row.revision,p_answers:submitted,p_finalize:finalize});if(key!==currentKey()||response?.id!==row.id)return;
          response=saved;dirty=JSON.stringify(answers)!==JSON.stringify(submitted);if(!dirty)answers=JSON.parse(JSON.stringify(saved.answers||{}));persist();if($('formsSaveStatus'))$('formsSaveStatus').textContent=dirty?'Salvando novas alterações…':'Rascunho salvo no servidor';
          if(finalize){localStorage.removeItem(localKey(saved));response=null;answers={};dirty=false;clearInterval(clock);await loadOwn();renderCatalog();showDetail(saved);notify('Formulário finalizado. Resultado registrado no acompanhamento.');}
        }finally{setBusy(false);}
      };
      saveChain=saveChain.catch(()=>{}).then(operation);return saveChain;
    }
    function showAnswerErrors(errors){if(errors[0].person)activePerson=errors[0].person;const index=response.schema_snapshot.sections.findIndex(s=>s.fields.some(f=>f.id===errors[0].id));if(index>=0)sectionIndex=index;renderResponse();const box=$('formsAnswerErrors');box.classList.remove('hidden');box.textContent=errors.map(e=>e.message).join(' ');$(`fm-answer-${errors[0].id}${errors[0].person?'-'+errors[0].person:''}`)?.scrollIntoView({block:'center',behavior:'smooth'});}

    // Relatórios, agendas e eventos são definidos abaixo para compartilhar o mesmo escopo.
    function filterDates(){const today=F.localDay(new Date()),year=Number(reportFilter.year||today.slice(0,4)),annual=['execution','charts','conformity'].includes(reportTab);return {from:annual?`${year}-01-01`:reportFilter.from||today.slice(0,7)+'-01',to:annual?`${year}-12-31`:reportFilter.to||today,year};}

    function myRows(){return myEvaluations.filter(r=>!myForm||r.form_id===myForm);}
    async function loadMyEvaluations(){
      if(!can('FORMS_SELF_VIEW'))throw Error('FORBIDDEN');
      if(!Number.isInteger(myYear)||myYear<2020||myYear>2100)throw Error('Informe um ano entre 2020 e 2100.');
      const key=currentKey(),token=++generation,rows=[],year=myYear;loading=true;renderMyEvaluations();
      try{for(let offset=0;offset<10000;offset+=250){const data=await rpc('my_form_evaluations',{p_unit:ctx().unit,p_from:year+'-01-01',p_to:year+'-12-31',p_offset:offset});if(key!==currentKey()||token!==generation)return;rows.push(...(data||[]));if(!data||data.length<250)break;if(offset===9750)throw Error('Há mais de 10.000 avaliações neste ano. Solicite ao administrador uma consulta por período.');}myEvaluations=rows;}finally{if(key===currentKey()&&token===generation){loading=false;renderMyEvaluations();}}
    }
    function selfPlanHtml(row,f){const key=F.planField(f,row.evaluated_user_id),p=row.own_plans?.find(p=>p.field_id===key);return p?`<div class="fm-self-plan"><strong>Plano de ação · ${p.status==='DONE'?'Concluído':'Em aberto'}</strong><p>${E(p.description)}</p><small>${E(p.responsible_name)}${p.due_date?' · Prazo: '+day(p.due_date):''}</small>${p.completion_note?`<p>${E(p.completion_note)}</p>`:''}</div>`:'';}
    function renderMyEvaluations(){
      const box=rootFor('forms-self');if(!box)return;const rows=myRows(),models=[...new Map(myEvaluations.map(r=>[r.form_id,{value:r.form_id,label:r.form_name}])).values()].sort((a,b)=>a.label.localeCompare(b.label));
      box.innerHTML=head('MEUS RESULTADOS',myEvolution?'Minha evolução por pergunta':'Minhas avaliações',`${ctx().profile?.name||'Colaborador'} · ${ctx().unit} · ${myYear}`,myEvolution?btn('self-back','← Voltar às avaliações'):btn('self-export','Baixar meus resultados'))+
       (myEvolution?'':`<div class="card"><div class="fm-self-filters">${field('Ano',`<input type="number" min="2020" max="2100" data-fm-self-filter="year" value="${myYear}">`)}${field('Formulário',`<select data-fm-self-filter="form">${options(models,myForm)}</select>`)}${btn('self-filter','Consultar','','primary')}</div><p class="fm-help">Aqui aparecem as avaliações finalizadas em que você foi avaliado. As respostas de grupo também fazem parte do seu resultado. N/A não reduz sua aderência.</p></div>`)+
       (loading?'<div class="card" role="status">Carregando suas avaliações…</div>':metrics(rows,'Minhas avaliações')+(myEvolution?personEvolutionHtml(rows,ctx().user.id,myYear):`<div class="fm-self-section-head"><h2>Meu histórico</h2>${btn('self-evolution','Ver evolução por pergunta')}</div><div class="fm-self-grid">${rows.map(r=>`<article class="card fm-self-result"><div class="fm-model-top"><small>${E(r.code)}</small>${badge(pct(r.score),tone(r.score))}</div><h2>${E(r.form_name)}</h2><p>${E(r.evaluated_area)} · ${fmt(r.completed_at)}</p><div class="fm-self-counts"><span class="good"><strong>${r.ok_count}</strong> OK</span><span class="bad"><strong>${r.nok_count}</strong> NOK</span><span class="warn"><strong>${r.na_count}</strong> N/A</span></div><small>Aplicado por ${E(r.respondent_name)}</small><div class="actions">${btn('self-detail','Ver minha avaliação',`data-id="${E(r.id)}"`,'primary')}${btn('self-pdf','PDF',`data-id="${E(r.id)}"`)}</div></article>`).join('')||empty('Você ainda não tem avaliações neste filtro','As avaliações aparecerão aqui depois que forem finalizadas pelo aplicador.')}</div>`));
    }
    function dayEnd(value){const d=new Date(value+'T00:00:00-03:00');d.setUTCDate(d.getUTCDate()+1);return d.toISOString();}
    async function loadPlans(rows){const result=[];for(let i=0;i<rows.length;i+=100){const ids=rows.slice(i,i+100).map(r=>r.id);if(ids.length)result.push(...await allRows('form_action_plans',q=>q.in('response_id',ids).order('created_at')));}return result;}
    async function loadReport(){
      const key=currentKey(),token=++generation,dates=filterDates();if(dates.from>dates.to)throw Error('A data inicial deve ser anterior à final.');
      loading=true;renderReport();
      try{const rows=await allRows('form_responses',q=>{q=q.eq('unit',ctx().unit).neq('status','CANCELLED').gte('started_at',dates.from+'T00:00:00-03:00').lt('started_at',dayEnd(dates.to)).order('started_at',{ascending:false}).order('id');if(reportFilter.form)q=q.eq('form_id',reportFilter.form);if(reportFilter.person&&reportTab!=='execution')q=q.eq('respondent_id',reportFilter.person);return q;});
        const [p,a]=await Promise.all([loadPlans(rows),allRows('form_assignments',q=>{q=q.eq('unit',ctx().unit).gte('due_date',dates.from).lte('due_date',dates.to).order('due_date');if(reportFilter.form)q=q.eq('form_id',reportFilter.form);if(reportFilter.person)q=q.eq('user_id',reportFilter.person);return q;})]);
        if(key!==currentKey()||token!==generation)return;responses=rows;plans=p;assignments=a;if(!people.length)await loadPeople();
      }finally{if(key===currentKey()&&token===generation){loading=false;renderReport();}}
    }
    function reportRowsFiltered(){return responses.filter(r=>(!reportFilter.area||r.form_area===reportFilter.area||(reportTab==='execution'&&r.schema_snapshot.evaluation?.area===reportFilter.area))&&(!reportFilter.type||findForm(r.form_id)?.form_type===reportFilter.type)&&(!reportFilter.search||F.key(r.form_name).includes(F.key(reportFilter.search))));}
    function metric(label,value,kind='neutral',detail=''){return `<article class="fm-metric ${kind}"><small>${E(label)}</small><strong>${E(value)}</strong>${detail?`<span>${E(detail)}</span>`:''}</article>`;}
    function metrics(rows,label=''){const s=F.summarize(rows);return `<div class="fm-metrics">${metric('Conformidade',pct(s.percent),tone(s.percent),'N/A fora do cálculo')}${metric(label||(reportTab==='execution'?'Avaliações concluídas':'Aplicações finalizadas'),s.completed,'brand')}${metric('Itens conformes',s.ok,'good')}${metric('Itens não conformes',s.nok,'bad')}${metric('Não se aplica',s.na,'warn')}</div>`;}
    function renderReport(){
      const box=rootFor('forms-report');if(!box)return;const dates=filterDates(),tabs=[['summary','Acompanhamento'],['applications','Aplicações / detalhado'],['execution','Controle de execução'],['farol','Farol'],['charts','Gráficos'],['conformity','Mapa de conformidades'],['issues','Inconsistências']],rows=reportRowsFiltered(),annual=['execution','charts','conformity'].includes(reportTab);
      if(reportTab==='execution'&&executionPerson){const rowsForPerson=F.assessmentRows(rows).filter(r=>r.evaluated_user_id===executionPerson),name=rowsForPerson[0]?.evaluated_name||people.find(p=>p.id===executionPerson)?.name||'Colaborador';box.innerHTML=head('EVOLUÇÃO INDIVIDUAL','Evolução por pergunta',`${name} · ${ctx().unit} · ${dates.year}`,btn('close-evolution','← Voltar ao controle de execução'))+metrics(rowsForPerson)+personEvolutionHtml(rows,executionPerson,dates.year);return;}
      box.innerHTML=head('RELATÓRIOS','Acompanhamento','Aplicações, resultados e planos de ação da unidade atual.',btn('export-csv','Baixar CSV')+btn('export-xlsx','Baixar Excel','','primary'))+
       `<div class="card fm-filter-card"><div class="fm-report-filters">${field('Unidade',`<input value="${E(ctx().unit)}" readonly>`)}${field('Formulário',`<select data-fm-filter="form">${options(definitions.map(f=>({value:f.id,label:f.name})),reportFilter.form)}</select>`)}${field(reportTab==='execution'?'Pessoa avaliada':'Aplicador',`<select data-fm-filter="person">${options(people.filter(p=>p.units.includes(ctx().unit)).map(p=>({value:p.id,label:p.name})),reportFilter.person)}</select>`)}${field('Área',`<select data-fm-filter="area">${options([...new Set(definitions.flatMap(f=>[f.area,f.schema.evaluation?.area].filter(Boolean)))].sort(),reportFilter.area,'Todas')}</select>`)}${field('Tipo',`<select data-fm-filter="type">${options(Object.entries(TYPES).map(([value,label])=>({value,label})),reportFilter.type)}</select>`)}${annual?field('Ano',`<input data-fm-filter="year" type="number" min="2020" max="2100" value="${dates.year}">`):field('Início das aplicações · de',`<input data-fm-filter="from" type="date" value="${dates.from}">`)+field('Até',`<input data-fm-filter="to" type="date" value="${dates.to}">`)}${btn('filter','Filtrar','','primary')}</div><p class="fm-help">Os resultados respeitam os acessos de cada formulário. As próprias aplicações também ficam disponíveis aqui.</p></div>`+
       `<div class="fm-tabs fm-report-tabs" role="tablist" aria-label="Visões de acompanhamento">${tabs.map(([id,label])=>`<button type="button" role="tab" aria-selected="${reportTab===id}" class="${reportTab===id?'active':''}" data-fm-action="report-tab" data-id="${id}">${label}</button>`).join('')}</div>`+
       (loading?`<div class="card" role="status">Carregando aplicações…</div>`:metrics(reportTab==='execution'?F.assessmentRows(rows).filter(r=>r.evaluated_user_id&&(!reportFilter.person||r.evaluated_user_id===reportFilter.person)):rows)+`<div id="formsReportBody">${reportTab==='summary'?summaryHtml(rows):reportTab==='applications'?applicationsHtml(rows):reportTab==='execution'?executionHtml(rows,dates.year):reportTab==='farol'?farolHtml(rows):reportTab==='charts'?chartsHtml(rows,dates.year):reportTab==='conformity'?conformityHtml(rows,dates.year):issuesHtml(rows)}</div>`);
    }
    function groupForms(rows){const map=new Map();for(const r of rows){if(!map.has(r.form_id))map.set(r.form_id,{id:r.form_id,name:r.form_name,area:r.form_area,rows:[]});map.get(r.form_id).rows.push(r);}return [...map.values()].sort((a,b)=>b.rows.length-a.rows.length);}
    function summaryHtml(rows){const groups=groupForms(rows);return `<div class="card"><div class="fm-card-title"><div><h2>Resultados por formulário</h2><p>${groups.length} formulários no filtro</p></div></div>${groups.length?`<div class="fm-table-wrap"><table class="fm-table"><thead><tr><th>Formulário</th><th>Área</th><th>Finalizados</th><th>Em andamento</th><th>Conformidade</th><th>Exportar</th></tr></thead><tbody>${groups.map(g=>{const s=F.summarize(g.rows);return `<tr><td><button class="fm-text-button" type="button" data-fm-action="report-form" data-id="${E(g.id)}">${E(g.name)}</button></td><td>${E(g.area)}</td><td>${s.completed}</td><td>${s.drafts}</td><td>${badge(pct(s.percent),tone(s.percent))}<div class="fm-progress ${tone(s.percent)}"><i style="width:${s.percent??0}%"></i></div></td><td>${btn('export-form','Excel',`data-id="${E(g.id)}"`)}</td></tr>`;}).join('')}</tbody></table></div>`:empty('Nenhuma aplicação neste período','Altere os filtros ou preencha um formulário publicado.')}</div>`;}
    function pager(total,size=25){return `<div class="fm-pagination"><span>${total?reportPage*size+1:0}–${Math.min((reportPage+1)*size,total)} de ${total}</span>${btn('page-prev','← Anterior',reportPage===0?'disabled':'')}${btn('page-next','Próxima →',(reportPage+1)*size>=total?'disabled':'')}</div>`;}
    function applicationsHtml(rows){const paged=rows.slice(reportPage*25,reportPage*25+25);return `<div class="card">${paged.length?responseRows(paged):empty('Nenhuma aplicação no filtro')}${pager(rows.length)}</div>`;}
    function executionHtml(rows,year){
      const assessed=F.assessmentRows(rows).filter(r=>r.status==='COMPLETED'&&r.evaluated_user_id),persons=new Map();for(const f of definitions.filter(f=>(!reportFilter.form||f.id===reportFilter.form)&&(!reportFilter.area||f.area===reportFilter.area)&&(!reportFilter.type||f.form_type===reportFilter.type))){if(!f.schema.evaluation?.enabled)continue;for(const p of people.filter(p=>p.units.includes(ctx().unit)&&F.key(p.area)===F.key(f.schema.evaluation.area)))persons.set(p.id,{...p,area:f.schema.evaluation.area});}for(const r of assessed)persons.set(r.evaluated_user_id,{id:r.evaluated_user_id,name:r.evaluated_name,role:r.evaluated_role,area:r.evaluated_area});const list=[...persons.values()].filter(p=>!reportFilter.person||p.id===reportFilter.person).sort((a,b)=>a.name.localeCompare(b.name));
      return `<div class="card"><div class="fm-card-title"><div><h2>Aderência por colaborador avaliado · ${year}</h2><p>Clique em um mês para abrir a evolução da pessoa por pergunta. Quem aplica o formulário não recebe a nota dos avaliados.</p></div></div><div class="fm-table-wrap fm-matrix-wrap"><table class="fm-table fm-matrix"><thead><tr><th>Pessoa avaliada / área</th>${F.MONTHS.map(m=>`<th>${m}</th>`).join('')}</tr></thead><tbody>${list.map(p=>`<tr><th>${E(p.name)}<small>${E(p.area)} · ${E(ctx().roles[p.role]||p.role)}</small></th>${F.MONTHS.map((m,i)=>{const rs=assessed.filter(r=>r.evaluated_user_id===p.id&&F.localDay(r.started_at).startsWith(`${year}-${String(i+1).padStart(2,'0')}`)),summary=F.summarize(rs);return `<td class="${summary.percent==null?'':summary.percent>=90?'fm-cell-good':summary.percent>=70?'fm-cell-warn':'fm-cell-bad'}">${btn('person-evolution',rs.length?`<strong>${pct(summary.percent)}</strong><small>${rs.length} avaliação(ões)</small>`:'—',`data-id="${E(p.id)}" data-month="${i+1}" aria-label="Evolução de ${E(p.name)} em ${m}"`,'fm-cell-button')}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>${!list.length?empty('Nenhuma pessoa avaliada neste filtro','Ative a avaliação de colaboradores no modelo. Registros antigos sem pessoas selecionadas continuam nos relatórios, sem atribuição retroativa.'):''}</div>`;
    }
    function personEvolutionHtml(rows,id,year){const person=F.assessmentRows(rows).find(r=>r.evaluated_user_id===id),name=person?.evaluated_name||people.find(p=>p.id===id)?.name||'Colaborador',questions=F.questionMonths(rows,id,year);return `<section class="card" id="formsPersonEvolution"><div class="fm-card-title"><div><h2>${E(name)} · evolução por pergunta</h2><p>Percentual de respostas conformes por mês · ${year}. N/A não reduz a aderência.</p></div></div><div class="fm-table-wrap fm-matrix-wrap"><table class="fm-table fm-matrix"><thead><tr><th>Pergunta / formulário</th>${F.MONTHS.map(m=>`<th>${m}</th>`).join('')}</tr></thead><tbody>${questions.map(q=>`<tr><th>${E(q.label)}<small>${E(q.form)}</small></th>${q.months.map(m=>`<td class="${m.percent==null?'':m.percent>=90?'fm-cell-good':m.percent>=70?'fm-cell-warn':'fm-cell-bad'}"><strong>${m.percent==null?'—':pct(m.percent)}</strong>${m.ok+m.nok+m.na?`<small>${m.ok} OK · ${m.nok} NOK${m.na?' · '+m.na+' N/A':''}</small>`:''}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${!questions.length?empty('Ainda não há perguntas avaliadas para essa pessoa'):''}</section>`;}

    function farolHtml(rows){
      if(!reportFilter.form)return `<div class="card">${empty('Selecione um formulário','O farol compara as respostas de cada aplicação, pergunta por pergunta.')}</div>`;
      const completed=F.assessmentRows(rows).filter(r=>r.status==='COMPLETED'),columns=completed.slice(reportPage*8,reportPage*8+8),questions=new Map();for(const r of completed)for(const f of F.fields(r.schema_snapshot))if(!questions.has(f.id))questions.set(f.id,f);
      if(!columns.length)return `<div class="card">${empty('Nenhuma aplicação finalizada no filtro')}</div>`;
      const row=(label,fn)=>`<tr><th>${label}</th>${columns.map(r=>`<td>${fn(r)}</td>`).join('')}</tr>`;
      return `<div class="card"><div class="fm-card-title"><div><h2>Farol das respostas</h2><p>As cores indicam conformidade. N/A não reduz a nota; perguntas de texto não recebem avaliação.</p></div></div><div class="fm-table-wrap fm-farol-wrap"><table class="fm-table fm-farol"><thead><tr><th>Pergunta / aplicação</th>${columns.map(r=>`<th><button type="button" class="fm-text-button" data-fm-action="detail" data-id="${E(r.id)}">${E(r.code)}</button><small>${E(r.evaluated_name||r.respondent_name)}</small></th>`).join('')}</tr></thead><tbody>${row('Início',r=>fmt(r.started_at))}${row('Finalização',r=>fmt(r.completed_at))}${row('Conformidade',r=>badge(pct(r.score),tone(r.score)))}${[...questions.values()].map(f=>`<tr><th><small>${E(f.section_title)}</small>${E(f.label)}</th>${columns.map(r=>{const historical=F.fields(r.schema_snapshot).find(q=>q.id===f.id);if(!historical)return '<td>Não constava nesta versão</td>';const a=r.answers?.[f.id],result=F.outcome(historical,a);return `<td class="fm-farol-${result||'TEXT'}"><strong>${E(F.answerText(historical,a))}</strong>${result?badge(result,result==='OK'?'good':result==='NOK'?'bad':'warn'):''}${a?.observation?`<small>${E(a.observation)}</small>`:''}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>${pager(completed.length,8)}</div>`;
    }
    function annualChart(rows,year,quality=false){
      const months=F.annual(rows,year),max=Math.max(1,...months.map(m=>m.completed)),left=44,top=26,width=900,height=210,step=width/12;
      const lines=Array.from({length:5},(_,i)=>{const y=top+height-i*height/4;return `<line x1="${left}" x2="${left+width}" y1="${y}" y2="${y}" stroke="#e6edf5"/><text x="${left-9}" y="${y+4}" text-anchor="end">${Math.round(max*i/4)}</text>`;}).join('');
      const bars=months.map((m,i)=>{const x=left+i*step+step*.23,h=m.completed/max*height;return `<g><title>${m.label}: ${m.completed} aplicações; conformidade ${pct(m.percent)}</title><rect x="${x}" y="${top+height-h}" width="${step*.54}" height="${h}" rx="4" fill="${quality?'#21a76a':'#2864e8'}"/><text x="${left+i*step+step/2}" y="${top+height+23}" text-anchor="middle">${m.label}</text></g>`;}).join('');
      const points=months.map((m,i)=>`${left+i*step+step/2},${top+height-(m.percent??0)/100*height}`).join(' ');
      return `<figure class="fm-chart"><svg viewBox="0 0 990 280" role="img" aria-label="Aplicações mensais em ${year}${quality?' e conformidade percentual':''}">${lines}${bars}${quality?`<polyline points="${points}" fill="none" stroke="#7c4de8" stroke-width="3"/><text x="980" y="20" text-anchor="end">Linha: 0–100%</text>`:''}</svg><figcaption>Quantidade de aplicações finalizadas por mês de início${quality?' · linha roxa: conformidade das respostas avaliadas':''}.</figcaption></figure>`;
    }
    function barRows(items,negative=false){const max=Math.max(1,...items.map(x=>x.count));return `<div class="fm-ranking">${items.map(x=>`<div><span title="${E(x.name)}">${E(x.name)}</span><div class="fm-rank-track"><i class="${negative?'bad':''}" style="width:${x.count/max*100}%"></i></div><strong>${x.count}</strong></div>`).join('')||empty('Nenhum resultado no filtro')}</div>`;}
    function chartsHtml(rows,year){return `<div class="card"><h2>Aplicações ao longo do ano · ${year}</h2>${annualChart(rows,year)}</div><div class="card"><h2>Formulários mais aplicados</h2>${barRows(groupForms(rows.filter(r=>r.status==='COMPLETED')).map(g=>({name:g.name,count:g.rows.length})))}</div>`;}
    function conformityHtml(rows,year){
      const negative=F.issues(rows),byQuestion=new Map(),all=new Map();for(const r of rows.filter(r=>r.status==='COMPLETED'))for(const f of F.fields(r.schema_snapshot)){if(f.scored){const k=r.form_id+':'+f.id;if(!all.has(k))all.set(k,{name:f.label,form:r.form_name,months:Array(12).fill(0)});}}
      for(const x of negative){const k=x.response.form_id+':'+x.field.id;if(!byQuestion.has(k))byQuestion.set(k,{name:x.field.label,count:0});byQuestion.get(k).count++;const m=Number(F.localDay(x.response.started_at).slice(5,7))-1;if(all.has(k)&&m>=0)all.get(k).months[m]++;}
      return `<div class="card"><h2>Evolução anual · quantidade e conformidade</h2>${annualChart(rows,year,true)}</div><div class="card"><h2>Ranking de não conformidades</h2>${barRows([...byQuestion.values()].sort((a,b)=>b.count-a.count),true)}</div><div class="card"><h2>Acompanhamento por pergunta · não conformidades</h2><div class="fm-table-wrap fm-matrix-wrap"><table class="fm-table fm-matrix"><thead><tr><th>Pergunta</th>${F.MONTHS.map(m=>`<th>${m}</th>`).join('')}</tr></thead><tbody>${[...all.values()].map(q=>`<tr><th>${E(q.name)}<small>${E(q.form)}</small></th>${q.months.map(n=>`<td class="${n?'fm-cell-bad':''}">${n||'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${!all.size?empty('Nenhuma pergunta avaliada no filtro'):''}</div>`;
    }
    function issuesHtml(rows){const all=F.issues(rows,plans),withPlan=all.filter(x=>x.plan),done=withPlan.filter(x=>x.plan.status==='DONE');return `<div class="fm-metrics three">${metric('Não conformidades',all.length,'bad')}${metric('Com plano de ação',withPlan.length,'brand')}${metric('Planos concluídos',done.length,'good')}</div><div class="card"><h2>Inconsistências e planos de ação</h2>${all.length?`<div class="fm-table-wrap"><table class="fm-table"><thead><tr><th>Formulário / registro</th><th>Colaborador</th><th>Pergunta / observação</th><th>Resposta</th><th>Plano / prazo</th><th>Ação</th></tr></thead><tbody>${all.slice(reportPage*25,reportPage*25+25).map(x=>`<tr><td><strong>${E(x.response.form_name)}</strong><small>${E(x.response.code)} · ${day(F.localDay(x.response.started_at))}</small></td><td>${E(x.response.evaluated_name||'Não informado')}<small>Aplicador: ${E(x.response.respondent_name)}</small></td><td><strong>${E(x.field.label)}</strong><small>${E(x.answer.observation||'Sem observação')}</small></td><td>${badge(F.answerText(x.field,x.answer),'bad')}</td><td>${x.plan?`${badge(STATUS[x.plan.status],x.plan.status==='DONE'?'good':'warn')}<small>${E(x.plan.responsible_name)} · ${day(x.plan.due_date)}</small>`:badge('Sem plano','bad')}</td><td>${btn('plan',x.plan?'Ver / editar plano':'＋ Plano',`data-id="${E(x.response.id)}" data-field="${E(F.planField(x.field,x.response.evaluated_user_id))}"`)}</td></tr>`).join('')}</tbody></table></div>${pager(all.length)}`:empty('Nenhuma não conformidade neste período')}</div>`;}
    let detailResponse=null;
    function showDetail(row){detailResponse=row;const s=F.score(row.schema_snapshot,row.answers);adapter.modal({title:row.form_name,subtitle:`${row.code} · ${row.unit} · versão ${row.form_version}`,html:`<div class="fm-detail-header"><div><small>APLICADOR</small><strong>${E(row.respondent_name)}</strong></div><div><small>INÍCIO</small><strong>${fmt(row.started_at)}</strong></div><div><small>FIM</small><strong>${fmt(row.completed_at)}</strong></div><div><small>DURAÇÃO</small><strong>${duration(row)}</strong></div><div><small>RESULTADO</small>${badge(pct(s.percent),tone(s.percent))}</div></div>${F.assessmentRows([row]).map(assessment=>`${assessment.evaluated_name?`<h2 class="fm-person-heading">${E(assessment.evaluated_name)} <small>${E(assessment.evaluated_area)}</small> ${badge(pct(assessment.score),tone(assessment.score))}</h2>`:''}${row.schema_snapshot.sections.map(section=>`<section class="fm-detail-section"><h3>${E(section.title)}<small>${section.fields.length} perguntas</small></h3>${section.fields.map(f=>{const a=assessment.answers?.[f.id],o=F.outcome(f,a);return `<div class="fm-detail-answer"><strong>${E(f.label)}</strong><div>${o?badge(F.answerText(f,a),o==='OK'?'good':o==='NOK'?'bad':'warn'):E(F.answerText(f,a))}</div>${a?.observation?`<p><b>Observação:</b> ${E(a.observation)}</p>`:''}${a?.plan?`<p><b>Plano inicial:</b> ${E(a.plan)}</p>`:''}${photoLinks(a)}${row._self_view?selfPlanHtml(row,f):''}${row.status==='COMPLETED'&&!row._self_view&&o==='NOK'?btn('plan','Plano de ação',`data-id="${E(row.id)}" data-field="${E(F.planField(f,assessment.evaluated_user_id))}"`):''}</div>`;}).join('')}${row.answers?.__sections?.[section.id]?`<div class="fm-detail-answer"><strong>Observações da seção</strong><p>${E(row.answers.__sections[section.id])}</p></div>`:''}</section>`).join('')}`).join('')}`,actions:btn(row._self_view?'self-export-one':'export-one','Baixar CSV',`data-id="${E(row.id)}"`)+(row.status==='COMPLETED'?btn(row._self_view?'self-pdf':'pdf','Baixar PDF',`data-id="${E(row.id)}"`,'primary'):'')});void refreshPhotoLinks();}
    async function openPlan(row,fieldId){
      if(!people.length)await loadPeople();const f=F.fields(row.schema_snapshot).find(f=>f.id===fieldId.split('@')[0]);if(!f)return;const subject=fieldId.split('@')[1];if(subject)row=F.assessmentRows([row]).find(r=>r.evaluated_user_id===subject)||row;
      const result=await rpcPlanFor(row.id,fieldId),p=result||{response_id:row.id,field_id:fieldId,description:row.answers?.[f.id]?.plan||'',responsible_id:row.respondent_id,due_date:'',status:'OPEN',completion_note:'',revision:0};
      planContext={row,fieldId,plan:p};
      adapter.modal({title:'Plano de ação',subtitle:f.label,html:`<p class="notice">${E(row.form_name)} · ${E(row.code)} · ${E(row.respondent_name)}</p><div class="fm-grid">${field('O que será feito? *',`<textarea id="formsPlanDescription" rows="4" maxlength="2000">${E(p.description)}</textarea>`,true)}${field('Responsável *',`<select id="formsPlanResponsible">${options(people.filter(u=>u.units.includes(row.unit)).map(u=>({value:u.id,label:u.name})),p.responsible_id,'Selecione')}</select>`)}${field('Prazo',`<input type="date" id="formsPlanDue" value="${E(p.due_date||'')}">`)}${field('Situação',`<select id="formsPlanStatus"><option value="OPEN" ${p.status==='OPEN'?'selected':''}>Em aberto</option><option value="DONE" ${p.status==='DONE'?'selected':''}>Concluído</option></select>`)}${field('Descrição da conclusão · obrigatória ao concluir',`<textarea id="formsPlanCompletion" rows="3" maxlength="2000">${E(p.completion_note||'')}</textarea>`,true)}</div>`,actions:btn('save-plan','Salvar plano','','primary')});
    }
    let planContext=null;
    async function rpcPlanFor(responseId,fieldId){const {data,error}=await ctx().client.from('form_action_plans').select('*').eq('response_id',responseId).eq('field_id',fieldId).maybeSingle();if(error)throw error;return data;}
    async function savePlan(){const c=planContext;if(!c||busy)return;busy=true;try{await rpc(c.fieldId.includes('@')?'save_form_evaluation_plan':'save_form_action_plan',{p_response_id:c.row.id,p_field_id:c.fieldId,p_expected_revision:c.plan.revision,p_payload:{description:$('formsPlanDescription').value,responsible_id:$('formsPlanResponsible').value,due_date:$('formsPlanDue').value,status:$('formsPlanStatus').value,completion_note:$('formsPlanCompletion').value}});adapter.closeModal();notify('Plano de ação salvo.');if(lastView==='forms-report')await loadReport();}finally{busy=false;}}
    async function exportData(kind,rows=reportRowsFiltered(),suppliedPlans=null){const currentPlans=suppliedPlans??(navigator.onLine?await loadPlans(rows):plans),matrix=F.exportRows(rows,currentPlans),name=`formularios_${F.localDay(new Date())}`;if(kind==='xlsx')return adapter.download(name+'.xlsx',new Blob([F.xlsx(matrix)],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));return adapter.download(name+'.csv',new Blob([F.csv(matrix)],{type:'text/csv;charset=utf-8'}));}
    let pdfLibPromise=null;
    async function pdfReport(row){
      if(!window.PDFLib){if(!pdfLibPromise)pdfLibPromise=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='vendor/pdf-lib.min.js';s.onload=resolve;s.onerror=()=>{pdfLibPromise=null;reject(Error('Não foi possível carregar o gerador de PDF.'));};document.head.append(s);});await pdfLibPromise;}
      const printedPhotos=new Set(),{PDFDocument,StandardFonts,rgb}=window.PDFLib,doc=await PDFDocument.create(),font=await doc.embedFont(StandardFonts.Helvetica),bold=await doc.embedFont(StandardFonts.HelveticaBold),width=595,height=842,margin=42;let page,y;
      const text=v=>String(v??'').replace(/[^\x20-\x7e\u00a0-\u00ff]/g,' ');
      const newPage=()=>{page=doc.addPage([width,height]);y=height-margin;page.drawRectangle({x:0,y:height-12,width,height:12,color:rgb(.1,.35,.82)});page.drawText('DISB GESTÃO | FORMULÁRIOS',{x:margin,y,font:bold,size:10,color:rgb(.1,.35,.65)});y-=27;};
      const line=(value,{size=10,strong=false,color=rgb(.12,.19,.28)}={})=>{const f=strong?bold:font,words=text(value).split(/\s+/);let out='';for(const word of words){if(f.widthOfTextAtSize((out?out+' ':'')+word,size)>width-margin*2&&out){draw(out);out=word;}else out+=(out?' ':'')+word;}draw(out);function draw(v){if(y<55)newPage();page.drawText(v,{x:margin,y,font:f,size,color});y-=size+6;}};
      newPage();line(row.form_name,{size:18,strong:true});line(`${row.code} | ${row.unit} | Versão ${row.form_version}`);line(`Aplicador: ${row.respondent_name}`);line(`Início: ${fmt(row.started_at)} | Fim: ${fmt(row.completed_at)}`);line(`Duração: ${duration(row)} | Conformidade: ${pct(row.score)}`,{strong:true});y-=12;
      for(const assessment of F.assessmentRows([row])){if(assessment.evaluated_name){if(y<120)newPage();line('Pessoa avaliada: '+assessment.evaluated_name,{size:13,strong:true});line('Área: '+assessment.evaluated_area+' | Conformidade: '+pct(assessment.score));}for(const section of row.schema_snapshot.sections){if(y<110)newPage();line(section.title,{size:13,strong:true});for(const f of section.fields){if(y<90)newPage();const a=assessment.answers?.[f.id],o=F.outcome(f,a);line(f.label,{strong:true});line(F.answerText(f,a),{color:o==='NOK'?rgb(.75,.13,.15):o==='OK'?rgb(.04,.45,.25):rgb(.2,.25,.33)});if(a?.observation)line('Observação: '+a.observation);if(a?.plan)line('Plano inicial: '+a.plan);for(const path of a?.photos||[]){if(printedPhotos.has(path)){line('Foto já apresentada neste relatório.',{size:9});continue;}const {data,error}=await photoOperation(ctx().client.storage.from('form-evidence').download(path));if(error)throw error;const bytes=await data.arrayBuffer(),img=path.endsWith('.png')?await doc.embedPng(bytes):await doc.embedJpg(bytes),scale=Math.min(1,(width-margin*2)/img.width,220/img.height),w=img.width*scale,h=img.height*scale;if(y-h<55){newPage();line(f.label+' · foto',{strong:true});}page.drawImage(img,{x:margin,y:y-h,width:w,height:h});y-=h+12;printedPhotos.add(path);}y-=7;}if(row.answers?.__sections?.[section.id])line('Observações da seção: '+row.answers.__sections[section.id]);y-=12;}}
      doc.getPages().forEach((p,i)=>p.drawText(`Disb Gestão | ${row.code} | ${i+1}/${doc.getPageCount()}`,{x:margin,y:25,font,size:8,color:rgb(.4,.45,.5)}));return adapter.download(`${row.code}.pdf`,new Blob([await doc.save()],{type:'application/pdf'}));
    }

    let scheduleFilter={},scheduleResults=[];
    function eligiblePerson(form,p){return !!form&&p.units.includes(ctx().unit)&&(p.role==='ADMIN'||form.apply_everyone||form.apply_roles.includes(p.role)||form.apply_user_ids.includes(p.id));}
    async function loadSchedule(){const key=currentKey(),today=F.localDay(new Date());scheduleFilter.from||=today.slice(0,7)+'-01';scheduleFilter.to||=today.slice(0,7)+'-'+new Date(Number(today.slice(0,4)),Number(today.slice(5,7)),0).getDate();if(scheduleFilter.from>scheduleFilter.to)throw Error('Revise o intervalo dos agendamentos.');const data=await allRows('form_assignments',q=>{q=q.eq('unit',ctx().unit).gte('due_date',scheduleFilter.from).lte('due_date',scheduleFilter.to).order('due_date').order('user_name');if(scheduleFilter.form)q=q.eq('form_id',scheduleFilter.form);if(scheduleFilter.person)q=q.eq('user_id',scheduleFilter.person);if(scheduleFilter.status)q=q.eq('status',scheduleFilter.status);return q;});const results=[],ids=data.map(a=>a.response_id).filter(Boolean);for(let i=0;i<ids.length;i+=100)results.push(...await allRows('form_responses',q=>q.in('id',ids.slice(i,i+100)).order('started_at')));if(key!==currentKey())return;assignments=data;scheduleResults=results;renderSchedule();}
    function renderSchedule(){
      const done=assignments.filter(a=>a.status==='COMPLETED').length,pending=assignments.filter(a=>a.status==='PENDING').length;
      rootFor('forms-schedule').innerHTML=head('AGENDAMENTOS','Agendamentos de formulários','Distribua aplicações por colaborador, unidade e data.',can('FORMS_MANAGE')?btn('new-schedule','＋ Novo agendamento','','primary'):'')+
       `<div class="card fm-report-filters">${field('Formulário',`<select data-fm-schedule-filter="form">${options(definitions.map(f=>({value:f.id,label:f.name})),scheduleFilter.form)}</select>`)}${field('Colaborador',`<select data-fm-schedule-filter="person">${options(people.filter(p=>p.units.includes(ctx().unit)).map(p=>({value:p.id,label:p.name})),scheduleFilter.person)}</select>`)}${field('Situação',`<select data-fm-schedule-filter="status">${options(['PENDING','COMPLETED','CANCELLED'].map(s=>({value:s,label:STATUS[s]})),scheduleFilter.status)}</select>`)}${field('Início',`<input type="date" data-fm-schedule-filter="from" value="${scheduleFilter.from}">`)}${field('Fim',`<input type="date" data-fm-schedule-filter="to" value="${scheduleFilter.to}">`)}${btn('schedule-filter','Filtrar')}</div>`+
       (scheduleFormOpen?scheduleEditor():'')+`<div class="fm-metrics">${metric('Total agendado',done+pending,'brand')}${metric('Realizados',done,'good')}${metric('Pendentes',pending,'warn')}${metric('Executado',done+pending?pct(done/(done+pending)*100):'—','brand')}${metric('Conformidade',pct(F.summarize(scheduleResults).percent),'good')}</div><div class="fm-tabs" role="tablist" aria-label="Visualização dos agendamentos">${[['list','Lista'],['calendar','Calendário']].map(([id,label])=>`<button type="button" role="tab" aria-selected="${scheduleView===id}" class="${scheduleView===id?'active':''}" data-fm-action="schedule-view" data-id="${id}">${label}</button>`).join('')}</div><div class="card">${scheduleView==='calendar'?calendarHtml():assignments.length?`<div class="fm-table-wrap"><table class="fm-table"><thead><tr><th>Formulário</th><th>Colaborador / unidade</th><th>Data prevista</th><th>Situação</th><th>Ações</th></tr></thead><tbody>${assignments.map(a=>{const f=findForm(a.form_id),late=a.status==='PENDING'&&a.due_date<F.localDay(new Date());return `<tr><td>${E(f?.name||'Formulário')}</td><td>${E(a.user_name)}<small>${E(a.unit)}</small></td><td>${day(a.due_date)}</td><td>${badge(late?'Atrasado':STATUS[a.status],late?'bad':a.status==='COMPLETED'?'good':'warn')}</td><td><div class="actions">${a.user_id===ctx().user.id&&a.status==='PENDING'&&fill(f)?btn('start-assignment','Iniciar / continuar',`data-id="${E(a.id)}"`):''}${a.response_id?btn('assignment-detail','Ver aplicação',`data-id="${E(a.response_id)}"`):''}${a.status==='PENDING'&&f&&manage(f)?btn('cancel-assignment','Cancelar',`data-id="${E(a.id)}"`):''}</div></td></tr>`;}).join('')}</tbody></table></div>`:empty('Nenhum agendamento no filtro','Os responsáveis verão aqui as aplicações atribuídas a eles.')}</div>`;
    }
    function calendarHtml(){const month=calendarMonth||scheduleFilter.from?.slice(0,7)||F.localDay(new Date()).slice(0,7),label=new Date(month+'-01T12:00:00Z').toLocaleDateString('pt-BR',{month:'long',year:'numeric',timeZone:'UTC'});return `<div class="fm-calendar-head">${btn('calendar-prev','← Mês anterior')}<h2>${E(label)}</h2>${btn('calendar-next','Próximo mês →')}</div><div class="fm-calendar-scroll"><div class="fm-calendar-inner"><div class="fm-calendar-week">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(d=>`<span>${d}</span>`).join('')}</div><div class="fm-calendar-grid">${F.calendarDays(month).map(date=>{const items=assignments.filter(a=>String(a.due_date).slice(0,10)===date);return `<section class="fm-calendar-day ${date.startsWith(month)?'':'other-month'} ${date===F.localDay(new Date())?'today':''}"><strong>${Number(date.slice(-2))}</strong>${items.map(a=>`<button type="button" class="fm-calendar-event ${a.status.toLowerCase()}" data-fm-action="calendar-assignment" data-id="${E(a.id)}"><b>${E(findForm(a.form_id)?.name||'Formulário')}</b><span>${E(a.user_name)}</span><small>${STATUS[a.status]}</small></button>`).join('')}</section>`;}).join('')}</div></div></div><p class="fm-help">O calendário respeita os filtros de formulário, colaborador e situação.</p>`;}
    async function changeCalendarMonth(delta=0){const current=calendarMonth||scheduleFilter.from?.slice(0,7)||F.localDay(new Date()).slice(0,7),date=new Date(current+'-01T12:00:00Z');date.setUTCMonth(date.getUTCMonth()+delta);calendarMonth=date.toISOString().slice(0,7);scheduleFilter.from=calendarMonth+'-01';const last=new Date(date);last.setUTCMonth(last.getUTCMonth()+1);last.setUTCDate(0);scheduleFilter.to=last.toISOString().slice(0,10);await loadSchedule();}
    function scheduleEditor(){const today=F.localDay(new Date());return `<section class="card fm-schedule-editor"><div class="fm-card-title"><div><h2>Novo agendamento</h2><p>Somente formulários publicados e colaboradores autorizados podem ser agendados.</p></div>${btn('close-schedule','Fechar')}</div><div class="fm-grid">${field('Formulário *',`<select id="formsScheduleModel"><option value="">Selecione</option>${definitions.filter(f=>f.status==='PUBLISHED'&&manage(f)).map(f=>`<option value="${E(f.id)}">${E(f.name)}</option>`).join('')}</select>`,true)}${field('Unidade',`<input readonly value="${E(ctx().unit)}">`)}${field('Repetição',`<select id="formsScheduleRepeat"><option value="ONCE">Uma vez</option><option value="DAILY">Todos os dias</option><option value="WEEKLY">Dias da semana</option><option value="BIWEEKLY">Quinzenal · a cada 15 dias</option><option value="MONTHLY">Mensal · mesmo dia</option></select>`)}${field('Data inicial *',`<input id="formsScheduleStart" type="date" value="${today}">`)}${field('Data final *',`<input id="formsScheduleEnd" type="date" value="${today}">`)}<div id="formsScheduleWeekdays" class="fm-wide hidden">${choices('schedule_weekdays',['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map((label,value)=>({value:String(value),label})),[])}</div><div class="fm-wide"><label class="fm-help">Colaboradores *</label><input type="search" class="fm-people-search" aria-label="Buscar colaboradores para agendar" placeholder="Buscar colaborador"><div id="formsSchedulePeople">${empty('Escolha o formulário para selecionar os responsáveis')}</div></div></div><div class="actions right">${btn('save-schedule','Criar agendamento','','primary')}</div></section>`;}
    async function saveSchedule(){if(busy)return;const model=$('formsScheduleModel').value,users=[...document.querySelectorAll('[data-fm-schedule-user]:checked')].map(e=>e.value);if(!model||!users.length)throw Error('Selecione o formulário e os colaboradores.');busy=true;try{const count=await rpc('create_form_schedule',{p_form_id:model,p_unit:ctx().unit,p_users:users,p_start:$('formsScheduleStart').value,p_end:$('formsScheduleEnd').value,p_repeat:$('formsScheduleRepeat').value,p_weekdays:[...document.querySelectorAll('[data-fm-list="schedule_weekdays"]:checked')].map(e=>Number(e.value))});scheduleFormOpen=false;await loadSchedule();notify(`${count} agendamento(s) criado(s). Registros já existentes foram preservados.`);}finally{busy=false;}}
    const getQuestion=id=>builder?.schema.sections.flatMap(s=>s.fields).find(f=>f.id===id);
    const locateQuestion=id=>builder?.schema.sections.find(s=>s.fields.some(f=>f.id===id));
    function move(list,index,delta){const next=index+delta;if(next<0||next>=list.length)return;[list[index],list[next]]=[list[next],list[index]];}
    function refreshAnswerState(id,person){const f=F.fields(response.schema_snapshot).find(f=>f.id===id),a=answerBag(id,person)[id],negative=F.outcome(f,a)==='NOK',card=$(`fm-answer-${id}${person?'-'+person:''}`);if(!card)return;card.classList.toggle('has-nok',negative);card.querySelector('[data-fm-action="toggle-plan"]')?.classList.toggle('hidden',!negative);if(negative)card.querySelector('[data-fm-note-box]')?.classList.remove('hidden');else card.querySelector('[data-fm-plan-box]')?.classList.add('hidden');}
    function onInput(event){
      const target=event.target,subject=target.closest('[data-fm-person]')?.dataset.fmPerson||'';
      if(target.matches('.fm-people-search')){const term=F.key(target.value);target.parentElement.querySelectorAll('.fm-choice-list label,[data-fm-schedule-label]').forEach(label=>label.classList.toggle('hidden',!F.key(label.textContent).includes(term)));return;}
      if(target.id==='formsCatalogSearch'){catalogFilter.search=target.value;filterCatalog();return;}if(target.dataset.fmCatalogFilter){catalogFilter[target.dataset.fmCatalogFilter]=target.value;filterCatalog();return;}
      if(target.dataset.fmSelfFilter){if(target.dataset.fmSelfFilter==='year')myYear=Number(target.value);else myForm=target.value;return;}
      if(target.dataset.fmFilter){reportFilter[target.dataset.fmFilter]=target.value;return;}
      if(target.dataset.fmScheduleFilter){scheduleFilter[target.dataset.fmScheduleFilter]=target.value;return;}
      if(builder&&target.dataset.fmEvaluation){builder.schema.evaluation??={enabled:false,area:'',membership:'AREA'};builder.schema.evaluation[target.dataset.fmEvaluation]=target.type==='checkbox'?target.checked:target.value;rememberBuilder();return;}
      if(builder&&target.dataset.fmMeta){builder[target.dataset.fmMeta]=target.type==='checkbox'?target.checked:target.value;rememberBuilder();return;}
      if(builder&&target.dataset.fmSection){const s=builder.schema.sections.find(s=>s.id===target.dataset.fmSection);if(s)s.title=target.value;rememberBuilder();return;}
      if(builder&&target.dataset.fmList&&target.dataset.fmList!=='schedule_weekdays'){const name=target.dataset.fmList;builder[name]=[...document.querySelectorAll(`[data-fm-list="${name}"]:checked`)].map(e=>e.value);rememberBuilder();return;}
      if(builder&&target.dataset.fmQ){const q=getQuestion(target.dataset.id),name=target.dataset.fmQ;if(!q)return;q[name]=target.type==='checkbox'?target.checked:name==='options'?target.value.split('\n').map(F.clean).filter(Boolean):['min','max'].includes(name)?(target.value===''?null:Number(target.value)):target.value;rememberBuilder();return;}
      if(!response||response.status!=='DRAFT')return;
      if(target.dataset.fmAnswer){const id=target.dataset.fmAnswer,f=F.fields(response.schema_snapshot).find(f=>f.id===id);const bag=answerBag(id,subject);bag[id]??={};bag[id].value=f.type==='NUMBER'?(target.value===''?null:Number(target.value)):target.value;refreshAnswerState(id,subject);answerChanged();}
      if(target.dataset.fmMultiple){const id=target.dataset.fmMultiple;const bag=answerBag(id,subject);bag[id]??={};bag[id].value=[...document.querySelectorAll(`[data-fm-multiple="${id}"]:checked`)].map(e=>e.value);answerChanged();}
      if(target.dataset.fmNote){const bag=answerBag(target.dataset.fmNote,subject);bag[target.dataset.fmNote]??={};bag[target.dataset.fmNote].observation=target.value;answerChanged();}
      if(target.dataset.fmPlan){const bag=answerBag(target.dataset.fmPlan,subject);bag[target.dataset.fmPlan]??={};bag[target.dataset.fmPlan].plan=target.value;answerChanged();}
      if(target.dataset.fmSectionNote){answers.__sections??={};answers.__sections[target.dataset.fmSectionNote]=target.value;answerChanged();}
    }
    function onChange(event){
      const target=event.target;
      if(builder&&target.dataset.fmEvaluation==='enabled'){if(!builder.schema.evaluation.enabled)for(const f of F.fields(builder.schema))getQuestion(f.id).scope='GROUP';renderManage();return;}
      if(builder&&target.dataset.fmMeta==='apply_everyone'){renderManage();return;}
      if(builder&&target.dataset.fmQ&&['type','scored','allow_na','require_note','options'].includes(target.dataset.fmQ)){
        const q=getQuestion(target.dataset.id);if(!q)return;
        if(target.dataset.fmQ==='type'){q.scored=q.type==='BOOLEAN';q.expected=q.type==='BOOLEAN'?'YES':null;q.allow_na=true;q.require_note=true;if(q.type.includes('CHOICE'))q.options||=['Opção 1','Opção 2'];}
        if(q.type==='SINGLE_CHOICE'&&q.scored&&!(q.options||[]).includes(q.expected))q.expected=q.options?.[0]||'';
        rememberBuilder();renderManage();return;
      }
      if(target.dataset.fmAnswer&&F.fields(response?.schema_snapshot).find(f=>f.id===target.dataset.fmAnswer)?.type==='SINGLE_CHOICE'){renderResponse();return;}
      if(target.dataset.fmPhotoInput&&target.files?.length){void addPhotos(target.dataset.fmPhotoInput,[...target.files],target.closest('[data-fm-person]')?.dataset.fmPerson||'').catch(e=>notify(errorMessage(e),'error'));return;}
      if(target.id==='formsScheduleRepeat')$('formsScheduleWeekdays').classList.toggle('hidden',target.value!=='WEEKLY');
      if(target.id==='formsScheduleModel'){
        const model=findForm(target.value),eligible=people.filter(p=>eligiblePerson(model,p));
        $('formsSchedulePeople').innerHTML=eligible.length?`<div class="fm-choice-list">${eligible.map(p=>`<label data-fm-schedule-label><input type="checkbox" data-fm-schedule-user value="${E(p.id)}"><span>${E(p.name)} · ${E(ctx().roles[p.role]||p.role)}</span></label>`).join('')}</div>`:empty('Nenhum colaborador autorizado','Revise os acessos do formulário.');
      }
    }
    async function getResponse(id){const row=responses.find(r=>r.id===id)||(detailResponse?.id===id?detailResponse:null);if(row)return row;const {data,error}=await ctx().client.from('form_responses').select('*').eq('id',id).single();if(error)throw error;if(data.unit!==ctx().unit)throw Error('Esta aplicação pertence a outra unidade.');return data;}
    async function handleAction(action,target){
      const id=target.dataset.id,subject=target.closest('[data-fm-person]')?.dataset.fmPerson||'';
      switch(action){
        case 'self-filter':return loadMyEvaluations();
        case 'self-evolution':myEvolution=true;renderMyEvaluations();rootFor('forms-self')?.scrollIntoView({block:'start'});return;
        case 'self-back':myEvolution=false;renderMyEvaluations();return;
        case 'self-detail':{const row=myEvaluations.find(r=>r.id===id);if(row)return showDetail(row);return;}
        case 'self-pdf':{const row=myEvaluations.find(r=>r.id===id);if(row)return pdfReport(row);return;}
        case 'self-export-one':{const row=myEvaluations.find(r=>r.id===id);if(row)return exportData('csv',[row],(row.own_plans||[]).map(p=>({...p,response_id:row.id})));return;}
        case 'self-export':return exportData('csv',myRows(),myRows().flatMap(r=>(r.own_plans||[]).map(p=>({...p,response_id:r.id}))));
        case 'refresh':return enter(lastView);
        case 'new':return newBuilder();
        case 'edit':{const f=findForm(id);if(manage(f))newBuilder(f);return;}
        case 'duplicate':{const f=findForm(id);if(!manage(f))return;const copy=JSON.parse(JSON.stringify(f));delete copy.id;delete copy.version;copy.name=(f.name+' (cópia)').slice(0,200);copy.status='DRAFT';newBuilder(copy);return;}
        case 'restore-builder':{const saved=JSON.parse(localStorage.getItem(builderKey())||'null');if(saved){builder=saved;renderManage();}return;}
        case 'close-builder':if(confirm('Voltar à lista? A criação ficará guardada neste aparelho.')){rememberBuilder();builder=null;renderManage();}return;
        case 'builder-tab':builderTab=id;renderManage();return;
        case 'preview':adapter.modal({title:findForm(id).name,subtitle:'Prévia do formulário',html:previewHtml(findForm(id)),actions:''});return;
        case 'save-draft':return saveBuilder('DRAFT');
        case 'publish':return saveBuilder('PUBLISHED');
        case 'save-status':return saveBuilder(builder.status);
        case 'add-section':{const section={id:F.id(),title:`Seção ${builder.schema.sections.length+1}`,fields:[]};builder.schema.sections.push(section);rememberBuilder();renderManage();return;}
        case 'section-remove':if(builder.schema.sections.length===1)throw Error('Mantenha ao menos uma seção.');if(confirm('Remover esta seção e suas perguntas do modelo? Aplicações já iniciadas serão preservadas.')){builder.schema.sections=builder.schema.sections.filter(s=>s.id!==id);rememberBuilder();renderManage();}return;
        case 'section-up':case 'section-down':move(builder.schema.sections,builder.schema.sections.findIndex(s=>s.id===id),action==='section-up'?-1:1);rememberBuilder();renderManage();return;
        case 'add-question':{const s=builder.schema.sections.find(s=>s.id===id),q={id:F.id(),label:'',type:'BOOLEAN',required:true,scored:true,expected:'YES',allow_na:true,require_note:true,help:''};s.fields.push(q);editingField=q.id;rememberBuilder();renderManage();return;}
        case 'edit-question':editingField=editingField===id?'':id;renderManage();return;
        case 'question-remove':if(confirm('Remover esta pergunta do modelo?')){const s=locateQuestion(id);s.fields=s.fields.filter(f=>f.id!==id);rememberBuilder();renderManage();}return;
        case 'question-up':case 'question-down':{const s=locateQuestion(id);move(s.fields,s.fields.findIndex(f=>f.id===id),action==='question-up'?-1:1);rememberBuilder();renderManage();return;}
        case 'question-copy':{const s=locateQuestion(id),q=JSON.parse(JSON.stringify(getQuestion(id)));q.id=F.id();s.fields.splice(s.fields.findIndex(f=>f.id===id)+1,0,q);editingField=q.id;rememberBuilder();renderManage();return;}
        case 'catalog':if(uploading)throw Error('Aguarde o envio das fotos.');catalogFilter={};selectedForm='';response=null;clearInterval(clock);await loadOwn();renderCatalog();paintNav();return;
        case 'back-catalog':if(uploading)throw Error('Aguarde o envio das fotos.');if(dirty)await saveResponse(false);response=null;clearInterval(clock);await loadOwn();renderCatalog();return;
        case 'application-tab':for(const [key,name] of [['available','Available'],['drafts','Drafts'],['completed','Completed']])$(`formsApplication${name}`).classList.toggle('hidden',key!==id);target.parentElement.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===target));return;
        case 'start':return begin(id);
        case 'start-evaluated':{if(busy||!pendingStart)return;const people=[...document.querySelectorAll('[data-fm-list="start_people"]:checked')].map(e=>e.value);if(!people.length)throw Error('Selecione ao menos uma pessoa.');const key=currentKey(),p=pendingStart;busy=true;try{const row=await rpc('start_form_response_evaluated',{p_form_id:p.formId,p_unit:ctx().unit,p_id:F.id(),p_people:people,p_assignment_id:p.assignmentId});if(key!==currentKey())return;adapter.closeModal();pendingStart=null;await openResponse(row);}finally{busy=false;}return;}
        case 'resume':return openResponse(await getResponse(id));
        case 'answer':{const bag=answerBag(id,subject);bag[id]??={};bag[id].value=target.dataset.value;answerChanged();renderResponse();return;}
        case 'evaluated-person':if(uploading)throw Error('Aguarde o envio das fotos para trocar de pessoa.');activePerson=id;renderResponse();return;
        case 'photo-camera':case 'photo-gallery':target.closest('[data-fm-person]').querySelector(`[data-fm-photo-input="${id}"][data-source="${action==='photo-camera'?'camera':'gallery'}"]`)?.click();return;
        case 'photo-remove':{if(uploading)throw Error('Aguarde o envio das fotos.');const bag=answerBag(id,subject),entry=bag[id];entry.photos=(entry.photos||[]).filter(p=>p!==target.dataset.path);if(F.fields(response.schema_snapshot).find(f=>f.id===id)?.type==='PHOTO')entry.value=entry.photos;answerChanged();renderResponse();return;}
        case 'toggle-note':target.closest('[data-fm-person]').querySelector(`[data-fm-note-box="${id}"]`)?.classList.toggle('hidden');return;
        case 'toggle-plan':target.closest('[data-fm-person]').querySelector(`[data-fm-plan-box="${id}"]`)?.classList.toggle('hidden');return;
        case 'section':sectionIndex=Number(id);renderResponse();return;
        case 'next-section':sectionIndex=Math.min(sectionIndex+1,response.schema_snapshot.sections.length-1);renderResponse();rootFor('forms-fill').scrollIntoView({block:'start'});return;
        case 'previous-section':sectionIndex=Math.max(0,sectionIndex-1);renderResponse();return;
        case 'save-response':await saveResponse(false);if(navigator.onLine)notify('Respostas salvas.');return;
        case 'finish':return saveResponse(true);
        case 'discard':if(uploading)throw Error('Aguarde o envio das fotos.');if(confirm('Descartar este rascunho? O histórico de aplicações finalizadas não será alterado.')){clearTimeout(saveTimer);await saveChain.catch(()=>{});const current=response;await rpc('cancel_form_response',{p_id:current.id});localStorage.removeItem(localKey(current));response=null;answers={};dirty=false;clearInterval(clock);await loadOwn();renderCatalog();notify('Rascunho descartado.');}return;
        case 'person-evolution':executionPerson=id;renderReport();rootFor('forms-report')?.scrollIntoView({block:'start'});return;
        case 'close-evolution':executionPerson='';renderReport();return;
        case 'report-tab':executionPerson='';reportTab=id;reportPage=0;return loadReport();
        case 'filter':reportPage=0;return loadReport();
        case 'report-form':reportFilter.form=id;reportTab='applications';reportPage=0;return loadReport();
        case 'page-prev':reportPage=Math.max(0,reportPage-1);renderReport();return;
        case 'page-next':reportPage++;renderReport();return;
        case 'detail':case 'assignment-detail':return showDetail(await getResponse(id));
        case 'plan':return openPlan(await getResponse(id),target.dataset.field);
        case 'save-plan':return savePlan();
        case 'export-csv':return exportData('csv');
        case 'export-xlsx':return exportData('xlsx');
        case 'export-form':return exportData('xlsx',reportRowsFiltered().filter(r=>r.form_id===id));
        case 'export-one':return exportData('csv',[await getResponse(id)]);
        case 'pdf':return pdfReport(await getResponse(id));
        case 'new-schedule':scheduleFormOpen=true;renderSchedule();return;
        case 'close-schedule':scheduleFormOpen=false;renderSchedule();return;
        case 'save-schedule':return saveSchedule();
        case 'schedule-view':scheduleView=id;if(id==='calendar')calendarMonth=scheduleFilter.from?.slice(0,7)||F.localDay(new Date()).slice(0,7);renderSchedule();return;
        case 'calendar-prev':return changeCalendarMonth(-1);
        case 'calendar-next':return changeCalendarMonth(1);
        case 'calendar-assignment':{const a=assignments.find(a=>a.id===id),f=findForm(a.form_id);adapter.modal({title:f?.name||'Agendamento',subtitle:day(a.due_date),html:`<p><b>Colaborador:</b> ${E(a.user_name)}</p><p>${E(a.unit)} · ${STATUS[a.status]}</p>`,actions:(a.user_id===ctx().user.id&&a.status==='PENDING'&&fill(f)?btn('start-assignment','Iniciar / continuar',`data-id="${E(a.id)}"`,'primary'):'')+(a.response_id?btn('assignment-detail','Ver aplicação',`data-id="${E(a.response_id)}"`):'')});return;}
        case 'schedule-filter':calendarMonth=scheduleFilter.from?.slice(0,7)||calendarMonth;return loadSchedule();
        case 'start-assignment':{const a=assignments.find(a=>a.id===id);return begin(a.form_id,a.id);}
        case 'cancel-assignment':if(confirm('Cancelar este agendamento pendente?')){await rpc('cancel_form_assignment',{p_id:id});await loadSchedule();notify('Agendamento cancelado.');}return;
      }
    }
    document.addEventListener('input',onInput);
    document.addEventListener('change',event=>{onInput(event);onChange(event);});
    document.addEventListener('click',event=>{

      const target=event.target.closest('[data-fm-action]');if(!target)return;
      event.preventDefault();Promise.resolve(handleAction(target.dataset.fmAction,target)).catch(error=>notify(errorMessage(error),'error'));
    });
    window.addEventListener('beforeunload',event=>{if(dirty||builder||uploading){persist();rememberBuilder();event.preventDefault();event.returnValue='';}});
    window.addEventListener('online',()=>{if(dirty&&response)saveResponse(false).catch(e=>notify(errorMessage(e),'error'));});
    window.addEventListener('focus',()=>{if(identity&&navigator.onLine&&!builder&&!response)void start();});
    return {start,stop,enter,canChangeUnit,refresh:()=>enter(lastView||'forms-fill')};
  }
  window.DISB_FORMS_UI={create};
})();
